export type LegalSection = { heading: string; body: string };
export type LegalDocument = { title: string; description: string; version: string; effectiveDate: string; sections: LegalSection[] };

const BASE_LEGAL_DOCUMENTS: Record<string, LegalDocument> = {
  "privacy": { title: "Privacy Policy", description: "How PixlPush processes personal data in connection with its websites, accounts and services.", version: "2.0", effectiveDate: "13 October 2026", sections: [
    { heading: "Overview", body: "Version 2.0\n\nThis Privacy Policy explains how PIXLLOVE SOCIAL MEDIA APPLICATIONS DEVELOPMENT AND MANAGEMENT L.L.C. (“PixlPush”, “we”, “us” or “our”) processes personal data in connection with the PixlPush websites, applications, software-as-a-service platform, APIs, SDKs, customer support and related services.\n\nPixlPush is a business-to-business customer engagement platform that enables customers to manage audiences, analytics, automations, email, mobile push and in-app communications. This Policy applies both to personal data that PixlPush processes for its own business purposes and to Customer Data that PixlPush processes on behalf of its business customers." },
    { heading: "1. Who we are and how to contact us", body: "The operator and contracting party for PixlPush is:\n\nPIXLLOVE SOCIAL MEDIA APPLICATIONS DEVELOPMENT AND MANAGEMENT L.L.C.\n\nBuilding Name – ALSUAIDI / Plot Number 247-0 / Property Number 1F01\n\nDubai, United Arab Emirates\n\nPrivacy contact: contact@pixl-develop.com\n\nTelephone: +971 52 993 7054\n\nPixl-develop is a brand or development designation and is not a separate operator or contracting party for PixlPush.\n\nFor privacy requests, complaints or questions about this Policy, please contact us using the details above. If you use PixlPush on behalf of one of our customers, that customer may be the responsible controller for your personal data. In that case, please contact the relevant customer first." },
    { heading: "2. Scope and important terms", body: "This Policy applies to our public websites, account registration, workspaces, dashboards, APIs, SDKs, integrations, customer support, billing, security and use of the PixlPush platform.\n\n“Personal data” means information relating to an identified or identifiable individual. “Processing” includes collecting, recording, organizing, storing, using, disclosing, transmitting, changing, restricting and deleting personal data.\n\n“Customer” means a business or organization that subscribes to or uses PixlPush. “Customer Data” means data that a customer or its authorized users submit to, collect through or otherwise make available in PixlPush, including information about the customer’s end users.\n\n“End User” means an individual who uses a customer’s app, website or service, or whose data a customer processes through PixlPush." },
    { heading: "3. Our role: controller and processor", body: "PixlPush acts as an independent controller for personal data used for our own business purposes. This includes account administration, authentication, organization and workspace contacts, contracting, billing, customer support, security, service integrity, abuse prevention, marketing to business contacts, legal compliance and the establishment, exercise or defense of legal claims.\n\nFor Customer Data processed to provide campaign, analytics, automation, messaging, SDK, API, import, export or deletion functionality, PixlPush generally acts as the customer’s processor or service provider. The customer generally determines why and how its End User data is collected and used and acts as the controller or business.\n\nThe customer is responsible for:\n\n• selecting and documenting the legal basis for its processing;\n\n• providing appropriate privacy notices to its users;\n\n• obtaining and recording any required consents or permissions;\n\n• configuring integrations, audiences, SDKs, APIs and automations lawfully;\n\n• ensuring that its message content, sender identity and campaigns comply with applicable law;\n\n• responding to requests from its End Users; and\n\n• using Customer Data only in accordance with applicable law and its contractual obligations.\n\nOur Data Processing Addendum (“DPA”) governs processor processing and supplements this Policy. If the DPA conflicts with this Policy regarding Customer Data, the DPA governs that processing.\n\nPixlPush may act as an independent controller for limited processing required for security, fraud prevention, service integrity, spam and abuse prevention, legal compliance or the defense of claims. The parties do not become joint controllers merely because they use the PixlPush platform." },
    { heading: "4. Personal data we process", body: "The categories of personal data depend on how PixlPush is used, which features are enabled and what a customer or authorized user submits. They may include:\n\n4.1 Account and business contact data\n\nThis may include name, business email address, username, job title, company, organization details, telephone number, billing contact details and other information provided during registration, contracting, support or business communication.\n\n4.2 Authentication and access data\n\nThis may include password hashes or authentication tokens managed by the relevant identity service, email verification, password reset records, login events, multi-factor authentication status, session information, role, permissions, workspace membership and access-control actions.\n\n4.3 Workspace and configuration data\n\nThis may include project identifiers, workspace settings, integrations, API credentials or tokens, sender information, domain configuration, audience configuration, automation rules and administrative actions.\n\n4.4 Technical and device data\n\nThis may include IP address, browser type, operating system, device or SDK identifiers, language, time zone, connection information, request timestamps, referrer information, error reports, diagnostic information, security events and service logs.\n\n4.5 Customer-supplied End User data\n\nDepending on the customer’s configuration, this may include external user identifiers, name, email address, country or region, language, time zone, device identifiers, mobile push tokens, consent or preference status and other customer-defined properties.\n\n4.6 Events and product interaction data\n\nThis may include SDK or API events, app or website interactions, subscription or paywall events supplied by a customer, onboarding, engagement, retention and churn-related signals, analytics records and campaign performance data.\n\n4.7 Campaign and messaging data\n\nThis may include audience and segment membership, campaign content, templates, scheduled or queued messages, journey rules, email addresses, mobile push data, in-app message content, delivery status, opens or clicks where enabled, bounce and complaint information, unsubscribe records and suppression data.\n\n4.8 Support and communications data\n\nThis may include support requests, messages, attachments, troubleshooting information, feedback, survey responses and correspondence with PixlPush.\n\n4.9 Billing and payment data\n\nThis may include subscription, invoice, tax and payment status, billing address, billing contact details and limited payment references. Stripe processes payment card details in its payment environment. PixlPush receives the payment and transaction references necessary to administer subscriptions, invoices and account status.\n\n4.10 AI data\n\nWhen a user invokes an AI feature, we may process prompts, instructions, source material, campaign content, translation text, analytics context, recommendations and generated outputs. Users should not enter unnecessary personal data, special-category data, passwords, payment credentials or confidential information into AI prompts.\n\n4.11 Website, cookie and marketing data\n\nThis may include consent preferences, cookie identifiers, advertising identifiers, website interaction data, campaign attribution data and information about how visitors use our websites. Non-essential analytics and advertising technologies are used only subject to applicable consent requirements.\n\nPixlPush does not require customers to submit every category listed above. Custom properties and event payloads are controlled by the customer and may contain personal data even where the field was not designed specifically for that purpose." },
    { heading: "5. Sensitive data and children", body: "PixlPush is designed for business marketing and customer-engagement use. Customers must not upload, collect through an SDK, send through an API, place in an AI prompt or otherwise process through PixlPush, unless expressly approved in writing after legal and technical review:\n\n• health, biometric, genetic, political, religious, philosophical, sexual-life or sexual-orientation data;\n\n• data about racial or ethnic origin, trade-union membership, criminal allegations or convictions;\n\n• precise or continuous location data;\n\n• highly sensitive financial information;\n\n• personal data relating to children or minors; or\n\n• other information requiring heightened legal protection.\n\nCustomers must filter such information before sending it to PixlPush and must not rely on PixlPush to detect or remove it. If such information is submitted, the customer must promptly notify PixlPush and cooperate with secure deletion or other appropriate measures.\n\nPixlPush is not directed to children. Customers must not use PixlPush to knowingly collect or process children’s personal data without all legally required approvals, notices and safeguards." },
    { heading: "6. Sources of personal data", body: "We receive personal data:\n\n• directly from account holders, workspace administrators and business contacts;\n\n• from customers and their authorized users through imports, SDKs, APIs and integrations;\n\n• automatically through the use of our websites, applications and platform;\n\n• from payment, identity, hosting, communications and other service providers;\n\n• through customer support, security and abuse-prevention communications;\n\n• from public business sources and business networking or marketing activities; and\n\n• from lawful requests, contractual records and business transactions.\n\nCustomers are responsible for ensuring that they are permitted to provide Customer Data to PixlPush." },
    { heading: "7. How we use personal data", body: "For personal data for which PixlPush is controller, we use personal data to:\n\n• create and administer accounts and workspaces;\n\n• authenticate users and manage permissions;\n\n• provide, operate, maintain and troubleshoot the platform;\n\n• provide customer support and service-related communications;\n\n• administer subscriptions, payments, invoices, taxes and contracts;\n\n• deliver, measure and improve the performance of our services;\n\n• monitor reliability, security, misuse, fraud, spam, deliverability, bounces, complaints and abuse;\n\n• maintain records, enforce our terms and policies and defend legal claims;\n\n• communicate with prospective and existing business customers;\n\n• send product updates, security notices and other legitimate business communications;\n\n• use aggregated or appropriately de-identified information to understand and improve the service;\n\n• comply with legal obligations and respond to lawful requests; and\n\n• protect the rights, property and safety of PixlPush, our customers, users and the public.\n\nFor Customer Data, we process the data on the customer’s documented instructions and under the DPA. PixlPush does not provide a blanket legal approval for a customer’s lists, tracking, profiling, campaigns or communications." },
    { heading: "8. Legal bases", body: "Where the GDPR, UK GDPR or a similar law applies, PixlPush relies on one or more of the following legal bases for controller processing:\n\n• performance of a contract or steps requested before entering a contract;\n\n• compliance with a legal obligation;\n\n• our legitimate interests in operating, securing, improving and protecting a business service, provided those interests are not overridden by the rights and interests of individuals; or\n\n• consent, where consent is legally required.\n\nWe do not treat acceptance of the Terms of Service or this Policy as consent to marketing, non-essential cookies, advertising or other processing for which separate consent is required.\n\nFor Customer Data, the customer determines the purposes and legal basis. The customer must ensure that its processing instructions are lawful." },
    { heading: "9. Account, authentication and workspace administration", body: "To register and use a workspace, we process account, authentication, organization, role and configuration data. PixlPush supports email-and-password registration, Google sign-in through Firebase, email verification, password reset and session management.\n\nWorkspace administrators control access and should assign permissions only to people who need them. Customers are responsible for their users’ actions and must promptly remove access when it is no longer needed.\n\nWe process sign-in and security events to authenticate users, prevent abuse, investigate incidents and protect the platform." },
    { heading: "10. Customer Data and use of the platform", body: "Customers may upload or transmit data through manual imports, SDKs, APIs or supported integrations. Depending on enabled features, PixlPush may store and organize End User records, custom properties, device identifiers, push tokens, permissions, preferences, events, audiences, segments, campaign content, automation rules, analytics and performance data.\n\nThe customer is responsible for its source data, privacy notices, collection methods, consent or other legal bases, SDK disclosures, audience selection, campaign content, sender identity, message timing, opt-outs and suppression rules. The customer must retain sufficient evidence showing when, how and for what purpose an email address, mobile identifier, push token or other contact record was collected, what notice was provided, what consent or other legal basis applied, and when any withdrawal or suppression request was received. PixlPush may request this evidence when investigating an abuse complaint, provider inquiry, legal request, security event or deliverability issue.\n\nCustomers must not upload purchased, rented, scraped or unlawfully obtained lists. PixlPush may suspend or restrict a workspace where we reasonably believe that Customer Data or communications violate law, our policies, security requirements or deliverability standards." },
    { heading: "11. Email, mobile push and in-app communications", body: "PixlPush provides tools for customers to create, schedule, automate, deliver and analyze email, mobile push and in-app communications. A customer-configured and activated journey may send messages automatically according to the customer’s rules.\n\nFor email delivery and delivery feedback, PixlPush uses Amazon Web Services’ Amazon Simple Email Service (SES) and Amazon Simple Notification Service (SNS). Depending on the feature, message content, recipient address, delivery metadata, bounce and complaint information may be processed.\n\nMobile push delivery may use customer-configured mobile services and relevant Google or Firebase infrastructure. In-app communications may use PixlPush SDKs, APIs and customer-configured application identifiers.\n\nCustomers must provide all notices and permissions required for email, push notifications, in-app messages, tracking, profiling and automated campaigns. Customers must implement clear opt-out and suppression controls and must respect device, browser and application notification settings. A recommendation from an AI feature does not by itself authorize or trigger a send. PixlPush is not responsible for a delivery failure caused by a recipient’s device settings, operating system, browser, network, carrier, app-store policy or third-party messaging provider." },
    { heading: "12. Artificial intelligence and automated features", body: "PixlPush offers optional AI-assisted features such as drafting, translation, text improvement, campaign suggestions, analytics explanations and recommendations.\n\nWhen a user invokes an AI feature, relevant prompts, instructions, source material and limited platform context are sent to Google Gemini through Google’s API infrastructure. We use a paid production configuration and do not use customer prompts, Customer Data or generated outputs for generalized training of Google’s public AI models.\n\nAI output may be inaccurate, incomplete, biased or unsuitable for a particular purpose. Users must review AI-generated content before publication or sending. AI features do not replace legal, compliance, security, marketing or professional advice.\n\nPixlPush does not use AI features to make decisions with legal or similarly significant effects about individuals. Customers must not use PixlPush AI features for credit, insurance, employment, housing, education, healthcare eligibility or other high-impact decisions.\n\nCustomers and users must not submit unnecessary personal data, special-category data, children’s data, authentication secrets, payment credentials or confidential third-party information to AI features." },
    { heading: "13. Cookies and similar technologies", body: "PixlPush uses cookies, pixels, local storage, SDK identifiers and similar technologies to operate websites and applications, maintain security, remember preferences, measure performance and understand how users interact with our services.\n\nWe use CookieYes to manage cookie consent and preferences.\n\nThe following technologies may be used on the relevant PixlPush websites and services, subject to applicable consent requirements:\n\n• Google Analytics for website and product analytics;\n\n• Google Ads for advertising measurement, campaign attribution and advertising;\n\n• Meta technologies for advertising measurement, campaign attribution and advertising; and\n\n• essential cookies and technical storage required for authentication, security, consent preferences and requested functionality.\n\nNon-essential analytics, personalization and advertising technologies are activated only where permitted by applicable law and the user’s consent choice. Visitors can change or withdraw consent through the available preference controls. More information is available in our Cookie Policy: https://pixl-push.com/legal/cookies" },
    { heading: "14. Service providers and recipients", body: "We disclose personal data to service providers where necessary to operate PixlPush, perform customer instructions, support our business, secure the platform or comply with law.\n\nDepending on the feature and service configuration, providers include:\n\n• Supabase – database, storage, authentication and backend infrastructure: https://supabase.com/privacy\n\n• Vercel – website hosting and deployment infrastructure: https://vercel.com/legal/privacy-policy\n\n• Cloudflare – domain, DNS and security-related infrastructure: https://www.cloudflare.com/privacypolicy/\n\n• Google Cloud and Firebase – cloud, authentication, application and messaging services: https://policies.google.com/privacy\n\n• Google BigQuery – configured analytics and data functions: https://cloud.google.com/terms/cloud-privacy-notice\n\n• Google Analytics – analytics and measurement: https://policies.google.com/privacy\n\n• Google Ads – advertising and advertising measurement: https://policies.google.com/privacy\n\n• Meta – advertising and advertising measurement: https://www.facebook.com/privacy/policies/\n\n• Google Gemini / Google AI Studio – user-invoked AI features: https://policies.google.com/privacy\n\n• Amazon SES and SNS – email delivery, mobile messaging and delivery feedback: https://aws.amazon.com/privacy/\n\n• Stripe – subscriptions and payment processing: https://stripe.com/privacy\n\n• CookieYes – cookie consent management: https://www.cookieyes.com/privacy-policy/\n\n• HubSpot – PixlPush’s own CRM and business relationship management: https://legal.hubspot.com/privacy-policy\n\nA provider may act as our processor or subprocessor for some activities and as an independent controller for its own billing, security, compliance or legal obligations. The provider’s own privacy notice governs that independent processing.\n\nWe may also disclose personal data to professional advisers, auditors, insurers, competent authorities, courts or law-enforcement bodies where lawful and necessary. Personal data may be disclosed in connection with a merger, financing, restructuring, acquisition or transfer of all or part of our business, subject to appropriate confidentiality and legal safeguards.\n\nOur DPA and Subprocessor information provide additional details for Customer Data. The current Subprocessor & Provider List is available at: https://docs.google.com/document/d/1K43OSFlRCMnM604G1h3RW61-jmBwlbybH8-b8Mi9W-U/edit" },
    { heading: "15. International data transfers", body: "PixlPush is operated from the United Arab Emirates and serves customers internationally. Personal data may be processed in the United Arab Emirates, the European Economic Area, the United Kingdom, the United States or other locations depending on the provider, feature and configuration.\n\nOur primary production database and storage services are configured to use an EU region where supported. Email delivery services are configured for the AWS eu-north-1 region. Website hosting and edge delivery may use globally distributed infrastructure.\n\nSome providers, including Google, Cloudflare, Vercel and other international service providers, may process data or permit support access from countries outside the EEA, the United Kingdom or Switzerland. Provider-specific locations and onward transfers are governed by the relevant provider terms and contractual safeguards.\n\nWhere a transfer is subject to the GDPR, UK GDPR, Swiss law or another transfer regime, PixlPush uses an approved transfer mechanism, such as an adequacy decision or Standard Contractual Clauses, together with supplementary measures where required." },
    { heading: "16. Retention and deletion", body: "We retain personal data only for as long as reasonably necessary for the purpose for which it was collected, the customer’s instructions, the contract, applicable law, security and abuse prevention, or the establishment, exercise or defense of legal claims.\n\nFor active accounts, we retain account and Customer Data while the account, workspace or customer relationship remains active and for the periods necessary to provide the service.\n\nFor frozen, cancelled and non-reactivated accounts:\n\n• operational Customer Data is retained for up to 12 months after the account enters the applicable frozen or inactive status;\n\n• at the end of that period, PixlPush provides a deletion notice and allows a further 30 days for export or other required action;\n\n• after that period, operational data is deleted or irreversibly anonymized, except where a documented legal, security or claims exception applies;\n\n• while an account is frozen, new users and tracking events are not stored and no new email or push messages are sent; and\n\n• no events missed during the frozen period are collected retroactively after reactivation.\n\nBackups are isolated from active systems and are overwritten or securely deleted no later than 30 days after deletion from the primary system, subject to technical recovery cycles and lawful retention exceptions.\n\nBilling, tax, contract and payment records may be retained for up to seven years or longer where required by applicable accounting, tax or limitation rules. Security, audit, support, AI conversation, bounce, complaint and suppression records are retained only for as long as necessary for their purpose. A minimal suppression record may be retained to honor an opt-out or prevent renewed abusive sending.\n\nCustomer Data is deleted or returned in accordance with the DPA and the customer’s instructions. Deletion from active systems may not immediately remove data from isolated backup copies during the applicable backup cycle." },
    { heading: "17. Security and incident response", body: "PixlPush applies technical and organizational measures designed to protect personal data against accidental loss, alteration, unauthorized access, disclosure or destruction.\n\nOur safeguards include, as appropriate:\n\n• role-based access controls and tenant separation;\n\n• authentication, authorization and session controls;\n\n• encryption in transit and protection of sensitive secrets;\n\n• secure handling of API keys and credentials;\n\n• security, audit and administrative logging;\n\n• rate limiting, abuse prevention and service monitoring;\n\n• patch and dependency management;\n\n• code review, testing and change control;\n\n• backups, recovery procedures and availability measures;\n\n• incident response and access review procedures; and\n\n• confidentiality obligations for persons who process personal data.\n\nNo online service can guarantee absolute security. Customers are responsible for protecting their credentials, configuring permissions correctly and notifying us promptly of suspected unauthorized access.\n\nIf we become aware of a personal data breach, we assess and respond to it and provide notices to customers, individuals or authorities when required by applicable law or contract. Where PixlPush acts as processor, we notify the affected customer in accordance with the DPA." },
    { heading: "18. Your privacy rights", body: "Depending on applicable law, individuals may have the right to:\n\n• request access to personal data;\n\n• request correction of inaccurate or incomplete data;\n\n• request deletion;\n\n• request restriction of processing;\n\n• request data portability;\n\n• object to processing based on legitimate interests;\n\n• withdraw consent where processing is based on consent; and\n\n• lodge a complaint with a competent data protection authority.\n\nRights are subject to legal exceptions, identity verification and the distinction between controller and processor processing.\n\nIf your data is processed by PixlPush on behalf of a customer, for example because you are an End User of a customer’s app or website, please contact that customer first. PixlPush assists the customer as required under the DPA and applicable law.\n\nFor account, business contact, website or other personal data that PixlPush processes as controller, contact us at contact@pixl-develop.com. We respond within the time required by applicable law." },
    { heading: "19. Additional information for United States residents", body: "Where applicable U.S. state privacy laws apply, residents may have rights to know or access, correct, delete, obtain a portable copy of or opt out of certain processing, as well as rights not to be discriminated against for exercising those rights.\n\nPixlPush does not sell personal data for money. If advertising technologies are enabled, certain disclosures may be treated as “sharing” or targeted advertising under some state laws. Where required, PixlPush provides an opt-out mechanism through applicable privacy or cookie settings and honors legally recognized opt-out signals.\n\nFor Customer Data, the customer generally determines the purposes and means of processing and acts as the business or controller. End Users should direct requests to the customer. Requests concerning PixlPush’s own controller data may be sent to the contact in Section 1." },
    { heading: "20. Profiling and automated decision-making", body: "PixlPush provides analytics, segmentation, churn and retention analysis, campaign performance reporting and recommendations. These features may evaluate events or attributes supplied by a customer to help that customer understand engagement or plan communications.\n\nThese features are not intended to decide whether an individual receives credit, insurance, employment, education, housing, healthcare or another service, or to make a decision with legal or similarly significant effects solely by automated means.\n\nCustomers must provide appropriate notice, use lawful data and criteria, assess profiling obligations and must not use PixlPush to discriminate or make prohibited high-impact decisions." },
    { heading: "21. Third-party websites and integrations", body: "The platform may link to third-party websites or connect with third-party services selected by a customer. Those organizations’ privacy notices and terms govern their own processing. PixlPush is not responsible for independent third-party practices.\n\nA customer’s integration may cause data to be sent directly between the customer and a provider. The customer is responsible for assessing, documenting and disclosing that data flow." },
    { heading: "22. Changes to this Policy", body: "We may revise this Policy when our services, providers, data practices or legal obligations change. The latest version will display its effective date.\n\nWhere required by law or contract, we provide notice of material changes or obtain any required agreement before a material change applies." },
    { heading: "23. Contact and complaints", body: "For questions, privacy requests or complaints about PixlPush’s own processing, contact:\n\nPIXLLOVE SOCIAL MEDIA APPLICATIONS DEVELOPMENT AND MANAGEMENT L.L.C.\n\nBuilding Name – ALSUAIDI / Plot Number 247-0 / Property Number 1F01\n\nDubai, United Arab Emirates\n\nEmail: contact@pixl-develop.com\n\nTelephone: +971 52 993 7054\n\nIf you are an End User whose data is processed through a customer’s PixlPush account, please contact that customer first. You may also complain to the data protection authority competent for your location or the relevant processing." },
    { heading: "24. Related documents", body: "This Privacy Policy should be read together with the following PixlPush Legal Hub documents:\n\n• PixlPush – Terms of Service;\n\n• PixlPush – Cookie Policy;\n\n• PixlPush – Acceptable Use Policy;\n\n• PixlPush – Anti-Spam Policy;\n\n• PixlPush – AI Policy;\n\n• PixlPush – Security & Privacy;\n\n• PixlPush – GDPR & Compliance Overview;\n\n• PixlPush – Data Processing Addendum (DPA);\n\n• PixlPush – Software Lifecycle & Versioning Policy;\n\n• PixlPush – Responsible Disclosure Policy;\n\n• PixlPush – Subprocessor & Provider List;\n\n• PixlPush – Legal Notice; and\n\n• PixlPush – SDK Terms & End-User License Agreement.\n\nThese documents are available through the PixlPush Legal Hub. They explain the contractual, security, product, SDK, provider and compliance rules that supplement this Privacy Policy. The Terms of Service identify which documents have contractual effect and when a document applies. This reference does not turn privacy information into consent to marketing, advertising or non-essential cookies. Cookie consent is handled separately where required. If this Policy conflicts with the DPA regarding the processing of Customer Data, the DPA governs that processing to the extent of the conflict.\n\nIf this Policy conflicts with the DPA regarding the processing of Customer Data, the DPA governs that processing to the extent of the conflict." },
  ] },
  "terms": { title: "Terms of Service", description: "The agreement governing use of the PixlPush platform and incorporated service policies.", version: "2.0", effectiveDate: "13 October 2026", sections: [
    { heading: "Overview", body: "Version 2.0\n\nThese Terms of Service (“Terms”) govern the Customer’s access to and use of PixlPush. PixlPush is a business-to-business software-as-a-service platform for customer engagement and lifecycle communication. Features may include audience management, imports, SDK and API integrations, email, mobile push and in-app messaging, campaigns, journeys, analytics, translations and AI-assisted tools.\n\nBy accepting these Terms electronically, signing an Order or accessing or using the Services, the Customer agrees to be legally bound by these Terms and the documents incorporated into them. If the person accepting these Terms acts for an organization, that person represents that they are authorized to bind that organization." },
    { heading: "1. Contracting party and scope", body: "The operator and contracting party for PixlPush is:\n\nPIXLLOVE SOCIAL MEDIA APPLICATIONS DEVELOPMENT AND MANAGEMENT L.L.C.\n\nBuilding Name – ALSUAIDI / Plot Number 247-0 / Property Number 1F01\n\nDubai, United Arab Emirates\n\nPixlPush, “we”, “us” and “our” refer to this legal entity. Pixl-develop is a brand or development designation and is not a separate operator, contracting party or liable entity.\n\nThese Terms apply to the business or other organization that registers for, purchases or uses the Services (“Customer”) and to the Customer’s Authorized Users. The Services are intended for commercial and professional use and are not offered for personal, family or household purposes." },
    { heading: "2. Definitions", body: "“Account” means the Customer’s PixlPush account, workspaces, projects, settings, subscriptions and related access credentials.\n\n“Authorized User” means an employee, contractor or other individual whom the Customer authorizes to access or use the Account.\n\n“Customer Data” means data, content, instructions, materials and information that the Customer or its Authorized Users submit to, collect through or make available to the Services, including data about End Users.\n\n“Customer Property” means the Customer’s applications, websites, digital products, domains, brands, content and other property connected to the Services.\n\n“End User” means an individual who uses, visits or receives communications from a Customer’s application, website, digital product or service.\n\n“Order” means an online plan selection, order form, subscription confirmation or other written commercial agreement accepted by PixlPush.\n\n“Services” means the PixlPush platform and its related websites, APIs, SDKs, documentation, support and features.\n\n“Service Data” means technical, usage, diagnostic, security, performance and operational information generated through use of the Services, excluding Customer Data that identifies the Customer’s End Users.\n\n“Agreement” means these Terms, the applicable Order, the Data Processing Addendum (“DPA”), the Privacy Policy, the Acceptable Use Policy (“AUP”), the Anti-Spam Policy, the AI Policy, the SDK Terms & End-User License Agreement and any other document expressly incorporated into these Terms." },
    { heading: "3. Acceptance and contract documents", body: "The Agreement is formed when an authorized representative accepts these Terms electronically, signs an Order, or otherwise accepts an offer from PixlPush and PixlPush activates the relevant Account or Services.\n\nThe PixlPush Legal Hub contains the following coordinated documents, which must be read together where relevant to the Services:\n\n• PixlPush – Terms of Service;\n\n• PixlPush – Privacy Policy;\n\n• PixlPush – Cookie Policy;\n\n• PixlPush – Acceptable Use Policy;\n\n• PixlPush – Anti-Spam Policy;\n\n• PixlPush – AI Policy;\n\n• PixlPush – Security & Privacy;\n\n• PixlPush – GDPR & Compliance Overview;\n\n• PixlPush – Data Processing Addendum (DPA);\n\n• PixlPush – Software Lifecycle & Versioning Policy;\n\n• PixlPush – Responsible Disclosure Policy;\n\n• PixlPush – Subprocessor & Provider List;\n\n• PixlPush – Legal Notice; and\n\n• PixlPush – SDK Terms & End-User License Agreement.\n\nThe Terms of Service, AUP, Anti-Spam Policy, AI Policy, applicable SDK Terms, applicable DPA, Orders, plan descriptions and SLAs have contractual effect as stated in the applicable document. The Privacy Policy, Cookie Policy and GDPR & Compliance Overview provide privacy and compliance information; Cookie consent is handled separately where required. Security & Privacy, the Software Lifecycle Policy and the Subprocessor List provide service and compliance information and are incorporated to the extent expressly stated in the Agreement or DPA. The Responsible Disclosure Policy applies to vulnerability reports, and the Legal Notice identifies the operator.\n\nIf documents conflict, the following order of precedence applies: a signed Order, the DPA for data protection matters, the applicable service-specific terms or SLA, these Terms, and then general policies. The Customer’s purchase order or other unilateral terms do not amend the Agreement unless PixlPush expressly accepts them in writing." },
    { heading: "4. Registration, accounts and security", body: "The Customer must provide accurate, complete and current registration, business, billing and contact information. The Customer must promptly update information that becomes inaccurate.\n\nThe Customer must be at least 18 years old or have full legal capacity to enter into the Agreement. The Customer must use the Services only for business or professional purposes.\n\nThe Customer is responsible for its Account, Authorized Users, credentials, devices and all activity carried out through its Account. The Customer must use reasonable security measures, keep credentials confidential, use strong passwords, enable available security controls and promptly notify PixlPush of suspected unauthorized access.\n\nThe Customer must not share individual credentials, permit unauthorized access, circumvent authentication, create accounts to evade limits or use another person’s Account without authorization.\n\nThe Customer is responsible for removing Authorized Users who no longer need access and for all instructions, configurations, integrations and campaigns created through its Account." },
    { heading: "5. Services and permitted access", body: "Subject to the Agreement and timely payment, PixlPush grants the Customer a limited, non-exclusive, non-transferable and revocable right for its Authorized Users to access and use the Services during the applicable subscription term.\n\nThe Customer may use the Services only for its internal business operations and only within the plan limits and documentation. The Customer must not:\n\n• resell, sublicense, rent, lease or provide the Services as a managed service to third parties unless expressly authorized;\n\n• copy, modify, translate, reverse engineer, decompile or attempt to discover the source code or underlying structure;\n\n• access the Services to build a competing product or service;\n\n• interfere with or disrupt the Services, infrastructure, networks or security controls;\n\n• bypass usage limits, access controls, rate limits or billing mechanisms;\n\n• use automated means to access the Services except through an authorized API or SDK;\n\n• probe, scan or test the Services for vulnerabilities without prior written authorization;\n\n• introduce malware, malicious code or harmful material;\n\n• use the Services to store or process unlawful, infringing or unauthorized data; or\n\n• permit any third party to do any of the above.\n\nPixlPush may modify, add or remove features, provided that we do not materially reduce the core functionality of a paid plan during its current prepaid term without a reasonable substitute or refund for the affected unused period." },
    { heading: "6. Plans, fees, billing and taxes", body: "The applicable plan, included features, usage limits, subscription interval, fees and payment terms are shown at checkout or in an Order. The Customer authorizes PixlPush and its payment processor, including Stripe where used, to charge the selected payment method for fees, applicable taxes, overages and other amounts due under the Agreement.\n\nPaid subscriptions renew automatically for successive periods matching the selected billing interval unless cancelled before the renewal date. The Customer may cancel through the Account billing settings or by contacting contact@pixl-develop.com. Cancellation takes effect at the end of the current paid period unless an Order states otherwise.\n\nThe Customer remains responsible for fees accrued through the effective cancellation date. Unless required by mandatory law or expressly stated in an Order, fees are non-refundable and no prorated refund is due for unused time, partial periods, downgrades, non-use or cancellation after a renewal charge. If PixlPush suspends, restricts or terminates an Account or Services because the Customer or an Authorized User breached these Terms, the AUP, the Anti-Spam Policy, the DPA, applicable law, payment obligations or any other applicable policy, the Customer is not entitled to a refund or credit for prepaid, unused or partially used fees, to the maximum extent permitted by law. Any refund, credit or goodwill payment that PixlPush may voluntarily provide is exceptional, discretionary, does not create a precedent or continuing right, and may be subject to conditions determined by PixlPush. Nothing in this section limits a refund or other remedy that cannot lawfully be excluded.\n\nPixlPush may change fees for a future subscription period by giving notice before the changed price takes effect. If the Customer does not accept a changed fee, it may cancel before the renewal date. Continued use after the new fee takes effect constitutes acceptance to the extent permitted by law.\n\nFees are exclusive of VAT, sales tax, withholding tax and similar taxes unless expressly stated otherwise. The Customer is responsible for taxes arising from its purchase, except taxes imposed on PixlPush’s net income. If the Customer is required to withhold tax, it must gross up the payment so that PixlPush receives the full amount invoiced, unless mandatory law prohibits this." },
    { heading: "7. Free plans, trials and plan limits", body: "PixlPush may offer a Free Plan, trial, promotional plan or preview feature. Eligibility, duration, usage limits, included features and any conversion to a paid subscription will be shown in the product, at checkout or in an Order.\n\nA trial or promotional period ends at the stated time. If it converts to a paid plan, the Customer must cancel before conversion if it does not wish to continue.\n\nFree Plans and trials may have lower limits or fewer features than paid plans. PixlPush may change or discontinue a Free Plan or trial on reasonable notice.\n\nIf the Customer reaches or exceeds a plan limit, PixlPush may prevent additional data, users, events or messages from being accepted, pause affected campaigns or features, ask the Customer to upgrade or apply overage charges only where disclosed in the applicable plan or Order.\n\nThe Customer must not create multiple or related Accounts to evade plan limits, trial restrictions, billing or enforcement measures." },
    { heading: "8. Customer Data and customer responsibilities", body: "As between the parties, the Customer retains its rights in Customer Data. The Customer is responsible for the accuracy, quality, legality, source, collection, notices, consents, permissions, retention and use of Customer Data and Customer Property.\n\nThe Customer represents and warrants that it has all rights, permissions and lawful bases necessary for PixlPush and its service providers to process Customer Data as instructed and to provide the Services.\n\nThe Customer is responsible for:\n\n• its relationship with End Users;\n\n• privacy notices and disclosures;\n\n• consent and preference records;\n\n• purposes and means of processing;\n\n• data-subject request procedures;\n\n• recipients, audiences and segmentation;\n\n• campaigns, message content and sender identity;\n\n• opt-outs, unsubscribes, push permissions, bounces and complaints;\n\n• the legality of its integrations and SDK implementation; and\n\n• compliance with applicable marketing, privacy, consumer-protection and communications laws.\n\nThe Customer must not upload purchased, rented, scraped or unlawfully collected contact lists. The Customer must not treat acceptance of these Terms, the existence of an email address or the possession of a device token as marketing consent where applicable law requires consent.\n\nPixlPush does not provide legal clearance for lists, campaigns, tracking, profiling, content or customer configurations." },
    { heading: "9. Privacy and data processing", body: "The Privacy Policy describes PixlPush’s controller processing. The DPA applies where PixlPush processes Customer Data as a processor or service provider.\n\nThe Customer authorizes PixlPush to process Customer Data as necessary to provide, secure, support and improve the Services, in accordance with the Customer’s documented instructions and the DPA.\n\nThe Customer must not instruct PixlPush to process data in a manner that violates applicable law or third-party rights. PixlPush may reject or suspend an instruction that presents a material legal, security or operational risk.\n\nThe Customer must not submit special-category personal data, children’s data, payment credentials, passwords, secrets or other highly sensitive information unless expressly permitted by the DPA or a written Order." },
    { heading: "10. Email communications", body: "The Customer may use email features only for lawful, permission-based and relevant communications. The Customer must comply with the Anti-Spam Policy and all applicable privacy, electronic communications, advertising and consumer-protection laws.\n\nEach email must identify the sender, must not use deceptive headers or subject lines and must include a clear, functional unsubscribe mechanism where required. Unsubscribe requests and suppression instructions must be honored promptly.\n\nThe Customer is responsible for its sending domains, sender identity, authentication records, message content, recipient lists, complaint rates, bounce rates and deliverability practices.\n\nPixlPush may pause or restrict sending where necessary to protect recipients, infrastructure, deliverability, providers or other customers." },
    { heading: "11. Mobile push and in-app communications", body: "The Customer may use mobile push and in-app features only where it has provided required notices and obtained required permissions.\n\nThe Customer is responsible for the lawful collection and use of device identifiers, push tokens, application identifiers, event data and preferences. The Customer must provide appropriate controls for notification permissions, opt-outs and preference changes.\n\nThe Customer must not use push or in-app messaging to send unlawful, deceptive, abusive, harassing or harmful content. PixlPush does not guarantee delivery because delivery may depend on device settings, operating systems, networks and third-party messaging services." },
    { heading: "12. Campaigns, journeys and automations", body: "The Customer is responsible for all campaigns, templates, journeys, automations, segments, schedules, triggers, rules and messages configured through its Account.\n\nA configured and activated journey may send messages automatically according to the Customer’s settings. The Customer must test and monitor automations and remains responsible for their operation.\n\nThe Customer must not configure a journey or automation to send content that is unlawful, misleading, discriminatory, abusive, unsolicited or inconsistent with the recipient’s permissions.\n\nPixlPush may delay, pause, block or cancel a campaign or automation where reasonably necessary for security, legal compliance, deliverability, abuse prevention, provider requirements or protection of recipients." },
    { heading: "13. AI features", body: "PixlPush may provide AI-assisted drafting, translation, text improvement, campaign suggestions, analytics explanations, recommendations and other AI features.\n\nAI features operate when an Authorized User actively invokes the relevant feature or gives an instruction. AI features do not independently authorize or trigger a message send. A campaign or journey configured and activated by the Customer may send automatically according to the Customer’s settings, including where the Customer uses AI-generated content.\n\nAI outputs may be incomplete, inaccurate, outdated, biased, non-unique or unsuitable. The Customer must review and verify all outputs before using, publishing or sending them, including for accuracy, rights, translation, accessibility, safety and legal compliance.\n\nThe Customer must not use AI features for fraud, phishing, spam, unlawful profiling, discrimination, deception, prohibited surveillance or decisions with legal or similarly significant effects.\n\nThe Customer must not submit personal data, special-category data, children’s data, authentication secrets, payment credentials or confidential third-party information to AI features unless it has the necessary rights and lawful basis.\n\nAI inputs and outputs that contain or derive from Customer Data are Customer Data. PixlPush does not use Customer Data to train general-purpose AI models. External AI providers and their processing are described in the Privacy Policy, DPA and Subprocessor List." },
    { heading: "14. Acceptable use and enforcement", body: "The Customer and its Authorized Users must comply with the AUP, Anti-Spam Policy and applicable law.\n\nThe Customer must not use the Services to:\n\n• send spam, phishing, fraudulent, deceptive or unsolicited messages;\n\n• upload purchased, rented, scraped or unlawfully obtained contacts;\n\n• facilitate unlawful activity, fraud, money laundering or sanctions violations;\n\n• promote terrorism, violence, exploitation, trafficking or criminal activity;\n\n• distribute child sexual abuse material or sexual exploitation content;\n\n• promote hate, harassment, bullying or unlawful discrimination;\n\n• infringe intellectual property, privacy, publicity or other rights;\n\n• distribute malware, ransomware, spyware or malicious code;\n\n• sell, share or broker personal data or contact lists unlawfully;\n\n• promote counterfeit goods, illegal goods or illegal services;\n\n• operate pyramid schemes, unlawful multi-level marketing or get-rich-quick schemes;\n\n• distribute deceptive health, financial, investment or political claims;\n\n• impersonate a person, company, public authority or brand;\n\n• publish or distribute misleading deepfake or manipulated media;\n\n• use the Services for high-impact automated decisions or prohibited profiling;\n\n• evade sanctions or provide Services to sanctioned persons or territories;\n\n• test or attack the Services without authorization; or\n\n• interfere with another user’s or customer’s use of the Services.\n\nPixlPush may investigate suspected violations using automated tools, security controls and human review where reasonably necessary. We may remove or restrict content, pause messages, block recipients, disable integrations, suspend Accounts or report conduct to competent authorities where required or reasonably appropriate." },
    { heading: "15. Third-party services and integrations", body: "The Services may interoperate with third-party services, applications, SDKs, APIs, payment providers, hosting providers, analytics providers and communication networks.\n\nThird-party services are governed by their own terms and privacy policies. PixlPush is not responsible for a third party’s availability, security, functionality, content, processing, fees or changes.\n\nThe Customer authorizes PixlPush to transmit relevant Customer Data to an integration selected or enabled by the Customer. The Customer is responsible for reviewing the third-party service, obtaining required permissions and configuring it lawfully.\n\nThird-party services may change, become unavailable or impose additional requirements. PixlPush may suspend or remove an integration where necessary for security, legal compliance, provider requirements or operational reasons." },
    { heading: "16. Intellectual property and licenses", body: "PixlPush and its licensors own all rights in the Services, software, interfaces, documentation, designs, trademarks, workflows, analytics methods and underlying technology. Except for the limited access right expressly granted in these Terms, no rights are transferred to the Customer.\n\nThe Customer retains its rights in Customer Data and Customer Property.\n\nThe Customer grants PixlPush a worldwide, non-exclusive, limited license to host, copy, transmit, process, display and otherwise use Customer Data and Customer Property only as necessary to provide, secure, support, maintain and improve the Services, comply with law, prevent abuse and perform the Agreement.\n\nThe Customer grants PixlPush a perpetual, irrevocable and royalty-free right to use feedback, suggestions and ideas about the Services without restriction, provided that PixlPush does not identify the Customer publicly without permission.\n\nPixlPush may use aggregated and de-identified data for analytics, security, benchmarking and service improvement, provided that the data cannot reasonably be used to identify the Customer or an individual.\n\nThe Customer represents and warrants that its Customer Data, Customer Property and use of the Services do not infringe third-party rights." },
    { heading: "17. Confidentiality", body: "Each party may receive non-public information from the other party that is marked confidential or that reasonably should be understood to be confidential (“Confidential Information”).\n\nThe receiving party must use Confidential Information only to perform or exercise rights under the Agreement, protect it with reasonable safeguards and disclose it only to personnel, advisers and service providers who need to know it and are bound by confidentiality obligations.\n\nConfidential Information does not include information that is publicly available without breach, already lawfully known, independently developed without use of the information or lawfully received from a third party without confidentiality duties.\n\nA party may disclose Confidential Information where required by law, provided that it gives advance notice where legally permitted and reasonably cooperates with protective measures.\n\nThe confidentiality obligations survive termination for five years. Trade secrets remain protected for so long as they qualify as trade secrets under applicable law." },
    { heading: "18. Frozen Accounts and service restrictions", body: "When a paid subscription expires or ends, the Account generally moves to the Free Plan if available. If the Account exceeds the applicable Free Plan limit or otherwise does not comply with the applicable plan, PixlPush may freeze the Account until the Customer upgrades, reduces usage, pays outstanding fees or restores compliance.\n\nWhile an Account is Frozen, PixlPush may stop accepting or storing new End Users or tracking events and may stop sending new email, push or in-app messages. Billing, payment, export and deletion functions remain available where technically possible.\n\nA Frozen status does not delete existing Customer Data or end the Customer’s obligations. Existing data remains subject to the retention and deletion rules in these Terms and the DPA." },
    { heading: "19. Availability, maintenance and support", body: "PixlPush will use reasonable efforts to make the Services available, but does not guarantee uninterrupted or error-free operation unless an applicable SLA expressly provides otherwise.\n\nThe Services may be unavailable or degraded because of maintenance, updates, emergencies, security events, provider outages, network failures, usage limits or events outside PixlPush’s reasonable control.\n\nPixlPush may perform scheduled or emergency maintenance and will provide reasonable notice where practicable.\n\nSupport availability, response times and channels depend on the applicable plan or Order. Support does not include legal, compliance, marketing, deliverability or professional advice." },
    { heading: "20. Suspension, investigation and termination", body: "PixlPush may restrict access, pause campaigns, hold messages, disable an integration or sending domain, block recipients, freeze an Account, suspend Services or terminate the Agreement where we reasonably believe that:\n\n• the Customer materially breached the Agreement;\n\n• fees are overdue;\n\n• use may violate law, the AUP or third-party rights;\n\n• the Account presents a security, fraud, abuse, spam or deliverability risk;\n\n• the Customer provided inaccurate or misleading information;\n\n• the Customer exceeded plan limits or attempted to evade them;\n\n• a provider, payment processor or authority requires action;\n\n• continued use could harm PixlPush, another customer, recipients or the public; or\n\n• suspension is necessary to investigate suspected misuse or protect the Services.\n\nWhere reasonably practicable, PixlPush will provide notice and an opportunity to remedy. We may act immediately where delay could cause harm, legal exposure, security risk, abuse, data loss or damage to deliverability.\n\nThe Customer may terminate its Account at any time through the available cancellation process or by written notice. Termination does not remove payment obligations accrued before termination.\n\nUpon termination, access ends and the Customer must stop using the Services. Sections intended by their nature to survive termination survive, including payment obligations, Customer responsibilities, intellectual property, confidentiality, indemnity, liability limitations, dispute resolution and data-retention provisions." },
    { heading: "21. Export, retention and deletion", body: "The Customer should export Customer Data it needs before cancelling, terminating or reaching a scheduled deletion date.\n\nFor frozen, cancelled and non-reactivated Accounts, PixlPush retains operational data for up to 12 months after the applicable frozen or inactive status begins. PixlPush then provides a deletion notice and allows a further 30 days for export or other required action.\n\nAfter that period, PixlPush deletes or irreversibly anonymizes operational data, except where retention is required or reasonably necessary for legal obligations, security, abuse prevention, billing, tax, audits, disputes or the establishment, exercise or defense of legal claims.\n\nBackups of deleted primary data are isolated from active systems and are overwritten or securely deleted no later than 30 days after deletion from the primary system, subject to the ordinary backup cycle and lawful retention exceptions.\n\nBilling, tax, payment, contract, security, abuse and legal evidence records may be retained for up to seven years or longer where required by law or reasonably necessary for legal claims.\n\nCustomer Data is returned or deleted in accordance with the DPA and the Customer’s instructions. If the DPA contains a more specific rule for Customer Data, the DPA controls." },
    { heading: "22. Warranties and disclaimers", body: "Each party represents that it has authority to enter into the Agreement.\n\nPixlPush will provide the Services in a professional manner consistent with the general description of the applicable plan or Order.\n\nExcept for express commitments in the Agreement and to the maximum extent permitted by law, the Services are provided “as available” and without warranties or conditions not expressly stated.\n\nPixlPush does not warrant that the Services will be uninterrupted, error-free, compatible with every system, secure against every threat or achieve a particular business result, campaign performance, deliverability, open rate, conversion, retention or revenue outcome.\n\nAnalytics, recommendations, translations and AI outputs are informational and may be based on incomplete data. The Customer is responsible for reviewing content, checking configurations, maintaining independent backups and assessing whether the Services are suitable for its requirements." },
    { heading: "23. Customer indemnity", body: "The Customer will defend, indemnify and hold harmless PixlPush, its affiliates, officers, employees, contractors and service providers against third-party claims, regulatory demands, losses, damages, fines, penalties, costs and reasonable legal fees arising from or relating to:\n\n• Customer Data, Customer Property, campaigns, content or messages;\n\n• the Customer’s failure to obtain required rights, permissions, consents or legal bases;\n\n• the Customer’s breach of the Agreement, AUP or applicable law;\n\n• the Customer’s infringement of privacy, intellectual property, publicity or other third-party rights;\n\n• the Customer’s use of an integration or third-party service; or\n\n• the acts or omissions of the Customer or its Authorized Users.\n\nPixlPush will give reasonably prompt notice of the claim, allow the Customer to control the defense and settlement and provide reasonable cooperation at the Customer’s expense.\n\nThe Customer may not settle a claim in a way that admits fault by PixlPush, imposes an obligation on PixlPush or restricts PixlPush’s rights without PixlPush’s prior written consent." },
    { heading: "24. Limitation of liability", body: "Nothing in the Agreement excludes or limits liability that cannot legally be excluded or limited, including liability for fraud, intentional misconduct, death or personal injury caused by negligence, or other non-waivable liability.\n\nTo the maximum extent permitted by law, neither party is liable for indirect, incidental, special, exemplary, punitive or consequential loss, or for loss of profit, revenue, anticipated savings, business opportunity, goodwill, reputation, use, data or business interruption, even if advised that such loss was possible.\n\nSubject to the first paragraph, PixlPush’s total aggregate liability arising out of or relating to the Agreement will not exceed the greater of:\n\n(a) the fees paid or payable by the Customer to PixlPush for the Services during the 12 months immediately preceding the event giving rise to the claim; or\n\n(b) AED 10,000.\n\nFor a Free Plan, PixlPush’s total aggregate liability is limited to AED 1,000.\n\nThe liability cap does not limit the Customer’s payment obligations, the Customer’s indemnity obligations, liability for infringement of PixlPush’s intellectual property, or liability that cannot legally be limited. The parties’ mandatory obligations under applicable data protection law remain effective.\n\nThe limitations in this section apply regardless of the legal theory of the claim and even if a remedy fails of its essential purpose." },
    { heading: "25. Force majeure", body: "Neither party is liable for delay or failure to perform caused by events beyond its reasonable control, including natural disasters, war, terrorism, civil unrest, government action, labor disputes, widespread internet or telecommunications failures, power outages, public health emergencies, cyberattacks not caused by the affected party’s failure to maintain reasonable safeguards, or failure of essential third-party infrastructure.\n\nThe affected party will take reasonable steps to limit the impact and resume performance. Force majeure does not excuse fees already due or obligations that can reasonably be performed despite the event." },
    { heading: "26. Changes to these Terms", body: "PixlPush may update these Terms to reflect changes in the Services, security, providers, law or business operations.\n\nThe current version will be posted in the PixlPush Legal Hub. We will provide advance notice of material changes where reasonably practicable.\n\nA change will not retroactively alter a dispute that arose before it took effect. If a change materially affects a paid Customer’s rights, the Customer may cancel the affected renewal before the change takes effect, subject to amounts already due and mandatory law.\n\nWhere law requires renewed acceptance, the Customer must accept the updated Terms to continue using the relevant Services." },
    { heading: "27. Governing law and dispute resolution", body: "These Terms and any non-contractual obligations arising out of or in connection with them are governed by the laws of the United Arab Emirates.\n\nThe parties will first attempt in good faith to resolve any dispute through discussions between authorized representatives. If the dispute is not resolved within 60 days after written notice of the dispute, it will be submitted to the exclusive jurisdiction of the courts of Dubai, United Arab Emirates.\n\nNothing in this section excludes mandatory legal provisions, mandatory rights or a forum that cannot validly be waived." },
    { heading: "28. General provisions", body: "The Customer may not assign or transfer the Agreement or any rights under it without PixlPush’s prior written consent. PixlPush may assign the Agreement to an affiliate or in connection with a merger, reorganization, acquisition or transfer of substantially all relevant assets, provided the assignee assumes the applicable obligations.\n\nPixlPush may use affiliates, subcontractors and service providers to perform parts of the Services, subject to the DPA where they process Customer Data.\n\nThe parties are independent contractors. The Agreement does not create a partnership, agency, employment relationship or joint venture.\n\nA failure or delay in enforcing a right is not a waiver. If a provision is found unenforceable, it will be modified to the minimum extent needed to make it enforceable, and the remaining provisions will continue in effect.\n\nThe Agreement is the complete agreement on its subject and replaces prior discussions on that subject. No third party has a right to enforce the Agreement unless mandatory law provides otherwise.\n\nElectronic acceptance, electronic records and electronic signatures may be used to form and evidence the Agreement to the extent permitted by law." },
    { heading: "29. Contact", body: "Questions about these Terms, billing or the Services may be sent to:\n\nPIXLLOVE SOCIAL MEDIA APPLICATIONS DEVELOPMENT AND MANAGEMENT L.L.C.\n\nBuilding Name – ALSUAIDI / Plot Number 247-0 / Property Number 1F01\n\nDubai, United Arab Emirates\n\nEmail: contact@pixl-develop.com\n\nTelephone: +971 52 993 7054\n\nPlease identify the Customer, Account and relevant Order when contacting PixlPush." },
  ] },
  "cookies": { title: "Cookie Policy", description: "How PixlPush uses cookies and similar technologies.", version: "2.0", effectiveDate: "13 October 2026", sections: [
    { heading: "Overview", body: "Version 2.0" },
    { heading: "1. Scope and purpose", body: "This Cookie Policy explains how PixlPush uses cookies and similar technologies on the PixlPush website, public web pages, account and dashboard areas, sign-up and login flows, and other web-based services operated by PixlPush.\n\nPixlPush is a retention and journey-automation platform for digital products. Our services help customers create audiences, analyse product engagement, automate user journeys, and deliver communications through channels such as email, in-app messaging and mobile push notifications. This Cookie Policy explains technologies used on PixlPush-controlled websites and web interfaces. It does not replace the Privacy Policy, Data Processing Addendum, Terms of Service or product-specific documentation.\n\nWhere PixlPush customers use our SDKs, APIs or mobile push functionality in their own applications, additional device identifiers, SDK technologies and app permissions may apply. Those processing activities are described in the applicable service documentation, customer instructions and the Privacy Policy." },
    { heading: "2. What are cookies and similar technologies?", body: "Cookies are small text files placed on a browser or device by a website. They allow a website to remember a device, session, settings or actions. Cookies may be set by PixlPush directly (first-party cookies) or by another provider whose service is used on the website (third-party cookies).\n\nPixlPush also uses technologies that perform similar functions, including local storage, session storage, pixels, tags, scripts, software development kits, web beacons and similar identifiers. These technologies may read or store information on a device, recognise a returning browser, maintain a login session, remember preferences, measure performance, or help us understand and improve campaigns and website communications.\n\nIn this Policy, “cookies” means cookies and all similar technologies unless a distinction is necessary." },
    { heading: "3. Why PixlPush uses cookies", body: "PixlPush uses cookies and similar technologies to:\n\n• keep the website, account areas and dashboard secure and functional;\n\n• maintain login sessions and protect accounts against abuse;\n\n• remember language, region, consent and other preferences;\n\n• provide the CookieYes consent interface and remember consent choices;\n\n• understand how visitors use our website and improve its performance;\n\n• measure the effectiveness of website content, campaigns and advertising;\n\n• attribute registrations and other actions to advertising campaigns;\n\n• detect technical errors, fraud, misuse and security events; and\n\n• deliver and measure relevant advertising where the applicable consent has been provided.\n\nCookies are not used to make consent to non-essential technologies a condition of using the website." },
    { heading: "4.1 Strictly necessary technologies", body: "Strictly necessary technologies enable core website and account functions. They may support login, authentication, security, session management, consent storage, load balancing, routing, fraud prevention and the operation of essential forms.\n\nThese technologies do not require consent where they are strictly necessary to provide a service requested by the visitor or to operate the website. They cannot be fully disabled through the CookieYes settings interface because disabling them may prevent login, account access or other core functions." },
    { heading: "4.2 Preference and functionality technologies", body: "Preference technologies remember choices such as language, region, display or interface settings. They make the website easier to use and can provide functionality requested by the visitor.\n\nWhere consent is required, PixlPush activates these technologies only after the relevant choice has been made." },
    { heading: "4.3 Analytics and performance technologies", body: "Analytics technologies help PixlPush understand website usage, traffic, performance, errors, navigation and interactions. PixlPush uses Google Analytics for analytics and performance measurement.\n\nAnalytics information may include pages viewed, interactions, approximate location, device and browser information, referral information, timestamps, campaign parameters and events relating to the website or sign-up process. Analytics technologies are used in accordance with the consent choices recorded through CookieYes." },
    { heading: "4.4 Advertising and marketing technologies", body: "Advertising technologies help PixlPush measure campaigns, understand conversions, attribute registrations and deliver or personalise advertising. PixlPush uses Google Ads and Meta technologies for advertising measurement, attribution, audience creation and campaign delivery.\n\nThese technologies may process information about visits, interactions, campaign parameters, conversions, browser or device characteristics and advertising events. They are used in accordance with the applicable consent choices and the relevant provider settings." },
    { heading: "5. Providers used by PixlPush", body: "PixlPush uses the following providers in connection with cookies and similar technologies:" },
    { heading: "5.1 CookieYes", body: "CookieYes provides the consent-management interface used by PixlPush. It displays cookie information, allows visitors to accept, reject or customise categories, stores the consent status and supports the withdrawal or change of consent.\n\nCookieYes provider policy: https://www.cookieyes.com/privacy-policy/" },
    { heading: "5.2 Google Analytics", body: "Google Analytics provides website analytics and performance measurement. PixlPush uses it to understand visits, navigation, interactions, technical performance and conversion events, and to improve the website and sign-up experience.\n\nGoogle Analytics privacy information: https://support.google.com/analytics/answer/6004245" },
    { heading: "5.3 Google Ads", body: "Google Ads provides advertising measurement, conversion attribution, campaign reporting, remarketing and related advertising functionality. PixlPush uses Google Ads to measure the performance of campaigns and understand actions such as visits, registrations and other conversion events.\n\nGoogle advertising and privacy information: https://policies.google.com/technologies/ads" },
    { heading: "5.4 Meta", body: "Meta technologies provide advertising measurement, campaign attribution, audience creation and advertising delivery functionality. PixlPush uses Meta technologies for campaign performance measurement and related advertising activities.\n\nMeta Privacy Policy: https://www.facebook.com/privacy/policy/\n\nThe providers’ own policies explain how those providers process information, use cookies and similar technologies, and handle rights or international transfers that may apply to their services." },
    { heading: "6. Cookie information and provider settings", body: "The Cookie Settings interface provides the current cookie categories and the technologies used on the relevant PixlPush website. Depending on the technology, the settings may show the provider, purpose, category and storage duration.\n\nCookies may be session cookies, which are removed when a browser session ends, or persistent cookies, which remain for a defined period or until they are deleted. Storage periods depend on the purpose of the technology, the provider configuration, security requirements and the visitor’s settings.\n\nPixlPush does not use a single storage period for all cookies. Essential session technologies may last only for the duration of a session, while consent records, preference technologies, analytics identifiers and advertising technologies may remain for longer periods as described in Cookie Settings or by the relevant provider." },
    { heading: "7. Consent and CookieYes", body: "When a visitor first accesses a PixlPush website, CookieYes presents information about the available cookie categories and allows the visitor to make a choice.\n\nDepending on the website configuration, a visitor may:\n\n• accept all available categories;\n\n• reject non-essential categories;\n\n• select individual categories; or\n\n• open Cookie Settings to review the available providers and purposes.\n\nConsent for non-essential cookies must be freely given, specific, informed and capable of being withdrawn. Access to the website, acceptance of the Terms of Service or continued browsing does not constitute consent to non-essential cookies.\n\nCookieYes records the consent choice, the time of the choice, the consent version and related technical information needed to demonstrate and manage the choice. The consent record is used to apply the visitor’s settings and to honour later changes or withdrawal." },
    { heading: "8. Changing or withdrawing consent", body: "Visitors can change or withdraw their consent at any time by selecting the Cookie Settings link or the CookieYes consent-settings control available on the relevant PixlPush website.\n\nA withdrawal applies to future processing based on that consent. Technologies that have already placed information on a device may need to be deleted through the Cookie Settings control or the browser settings. Withdrawal does not affect processing that was lawful before the withdrawal.\n\nStrictly necessary technologies remain active because they are required for core website, security, login or consent functions." },
    { heading: "9. Browser controls and global privacy signals", body: "Most browsers allow visitors to block, delete or restrict cookies. Browser instructions are available in the help section of the relevant browser.\n\nBlocking all cookies may affect login, account access, security features, language settings, consent storage or other core functions. Browser controls do not necessarily delete a consent record held by CookieYes, so visitors should use Cookie Settings to change or withdraw a recorded choice.\n\nWhere technically supported and legally applicable, PixlPush may consider recognised privacy signals or browser settings when configuring non-essential technologies. A privacy signal does not override strictly necessary technologies or security controls." },
    { heading: "10. Third-party links and services", body: "The PixlPush website may contain links to third-party websites, integrations or services. A link to a third-party site does not mean that PixlPush controls that site or its cookies.\n\nThird parties may place or access cookies and similar technologies when their content, links, integrations or services are used. Their processing is governed by their own privacy and cookie policies. Visitors should review those policies before using the relevant service." },
    { heading: "11. Cookies in the PixlPush product and customer environments", body: "PixlPush may use essential technologies in the customer dashboard and web application to maintain authentication, session security, workspace settings, navigation and account functionality.\n\nPixlPush customers may also configure communications, integrations, analytics, audience tracking and mobile push functionality in their own products. In those cases, PixlPush may process information on the customer’s behalf as a processor. The customer is responsible for providing appropriate notices, collecting required permissions and configuring its own product and SDK implementation lawfully.\n\nMobile push notifications are generally controlled through operating-system permissions and application identifiers rather than ordinary browser cookies. The relevant app permissions, device identifiers, SDK technologies and provider relationships are addressed in the Privacy Policy, customer documentation and applicable contractual terms." },
    { heading: "12. Security and protection", body: "PixlPush uses reasonable technical and organisational measures to protect cookie-related information and consent records against unauthorised access, alteration, disclosure or destruction.\n\nCookie information may be processed together with technical information such as IP address, browser type, device type, operating system, language, timestamps, referral data and security events where necessary for the purposes described in this Policy, the Privacy Policy or applicable law." },
    { heading: "13. International processing and provider policies", body: "PixlPush and the providers described in this Policy may process information in countries outside the visitor’s country of residence. Where required, PixlPush uses appropriate safeguards for international transfers and considers the applicable legal requirements.\n\nProvider-specific processing, international transfer mechanisms, retention practices and rights procedures are explained in the relevant provider policies:\n\n• CookieYes Privacy Policy: https://www.cookieyes.com/privacy-policy/\n\n• Google Analytics Privacy Information: https://support.google.com/analytics/answer/6004245\n\n• Google Advertising Policies and Privacy: https://policies.google.com/technologies/ads\n\n• Meta Privacy Policy: https://www.facebook.com/privacy/policy/" },
    { heading: "14. Relationship with the Privacy Policy", body: "This Cookie Policy should be read together with the PixlPush Privacy Policy. The Privacy Policy explains the controller and processor roles, categories of personal data, legal bases, retention, recipients, international transfers, data-subject rights and contact details.\n\nIf a cookie or similar technology processes personal data, the relevant information in the Privacy Policy also applies." },
    { heading: "15. Children", body: "PixlPush services are intended for business and professional use. PixlPush does not knowingly use cookies to collect personal data from children in violation of applicable law. If a visitor believes that a child has provided personal data through the website, they should contact PixlPush using the contact details in the Privacy Policy or Legal Notice." },
    { heading: "16. Changes to this Cookie Policy", body: "PixlPush may update this Cookie Policy when technologies, providers, website functionality, consent configurations or legal requirements change.\n\nThe effective date and version are shown at the beginning of this Policy. Material changes will be reflected in the Legal Hub and, where appropriate, through the CookieYes consent interface." },
    { heading: "17. Contact", body: "Questions about this Cookie Policy, cookie choices or privacy at PixlPush can be submitted through the contact details provided in the PixlPush Privacy Policy and Legal Notice.\n\nThe current Cookie Policy is available through the PixlPush Legal Hub." },
  ] },
  "aup": { title: "Acceptable Use Policy", description: "Rules for lawful and responsible use of PixlPush.", version: "2.0", effectiveDate: "13 October 2026", sections: [
    { heading: "Overview", body: "Version 2.0\n\nThis Acceptable Use Policy (“AUP”) forms part of the PixlPush Terms of Service and sets binding rules for the use of the PixlPush platform, APIs, SDKs, email, mobile push, in-app messaging, analytics, automations and AI-assisted features.\n\nThese rules protect PixlPush, customers, message recipients, infrastructure providers, delivery reputation and other users of the shared platform. A violation may result in message blocking, feature restrictions, suspension, termination and loss of prepaid fees as described in the Terms of Service." },
    { heading: "1. Permitted use", body: "PixlPush may be used only for lawful business or professional purposes and only in accordance with the Terms of Service, the Privacy Policy, the DPA, this AUP, the Anti-Spam Policy and applicable third-party provider rules.\n\nCustomers may create, analyze and send campaigns, audience segments, journeys, email, mobile push and in-app messages only where they have the necessary rights, permissions, notices, legal bases and consents.\n\nCustomers must use the Services only for applications, websites, digital products and business activities that they own, operate or are authorized to represent." },
    { heading: "2. Customer responsibilities", body: "The Customer is solely responsible for data and content processed through imports, SDKs, APIs, integrations, campaigns, journeys and AI features.\n\nThe Customer must:\n\n• have and document an appropriate legal basis and any required consents;\n\n• provide transparent privacy, cookie, push and marketing notices;\n\n• document the source, date, method, purpose and legal basis for contact data;\n\n• retain proof of consent and preference records for as long as required by applicable law and best practices;\n\n• provide consent records and other evidence promptly when PixlPush investigates a complaint or provider inquiry;\n\n• promptly honor unsubscribes, objections, suppression requests and push-notification preferences;\n\n• use accurate sender, domain, company and reply-to details;\n\n• authenticate and validate sending domains where required;\n\n• remain responsible for campaign content, links, landing pages and AI output;\n\n• handle data-subject requests and reasonably assist PixlPush with investigations;\n\n• comply with Apple, Google, Firebase, Amazon SES, payment provider, carrier, app store and integration requirements that apply to its use; and\n\n• ensure that Authorized Users and connected tools comply with this AUP.\n\nAt any time, PixlPush may require information reasonably necessary to verify a campaign, recipient source, consent record, sending domain, integration or lawful use of the Services." },
    { heading: "3. Prohibited contact sources", body: "The following contact sources are prohibited:\n\n• purchased, rented, borrowed or exchanged lists;\n\n• scraped, harvested or automatically collected addresses or identifiers;\n\n• lists obtained from a third party without consent that specifically covers the Customer’s communication;\n\n• public directories, websites or social-media profiles used without a valid legal basis and reasonable recipient expectation;\n\n• contacts that have opted out, complained, bounced permanently or requested suppression;\n\n• addresses or push tokens obtained through deception, coercion or unlawful tracking; and\n\n• contacts for which the Customer cannot demonstrate a lawful source and purpose.\n\nThe Customer must not use PixlPush to discover, verify, generate or infer unknown email addresses or mobile identifiers without the individual’s lawful permission." },
    { heading: "4. Prohibited content and activities", body: "Customers must not use PixlPush to:\n\n• send spam, phishing, malware, ransomware or fraudulent messages;\n\n• impersonate a person, company, public authority, brand or sender;\n\n• hide, forge or misrepresent sender, reply-to, domain, routing or identification information;\n\n• distribute content infringing intellectual property, privacy, publicity, trade-secret or other rights;\n\n• threaten, harass, exploit, discriminate against or endanger individuals or groups;\n\n• facilitate terrorism, trafficking, exploitation, violence, organized crime or criminal conduct;\n\n• distribute child sexual abuse material or sexual exploitation content;\n\n• operate unlawful gambling, investment, financial, debt-collection or get-rich-quick schemes;\n\n• promote counterfeit, stolen, illegal or heavily regulated goods or services;\n\n• distribute deceptive health, medical, political, financial or consumer claims;\n\n• send unlawful marketing or communications to children or minors;\n\n• process special-category or highly sensitive personal data without prior written approval;\n\n• use precise location, government identifiers, payment credentials, passwords or authentication secrets without a specifically approved legal and technical basis;\n\n• make or facilitate decisions with legal or similarly significant effects without required safeguards;\n\n• use the Services for high-risk activities where failure could cause death, serious injury, environmental damage or critical infrastructure failure;\n\n• use the Services to circumvent sanctions, export controls, anti-money-laundering or anti-corruption laws;\n\n• attack, scan, scrape, load-test or attempt to compromise the Services without written authorization;\n\n• circumvent rate limits, storage limits, security controls, billing or plan restrictions;\n\n• benchmark or evaluate the Services for competitive purposes without written permission;\n\n• build, train or operate a competing product using the Services or Service Data; or\n\n• use any content, integration or activity that could materially damage the reputation, deliverability or operation of PixlPush or its providers." },
    { heading: "4A. Restricted sectors and review-required use", body: "Certain sectors and campaign topics create elevated legal, abuse, deliverability or provider risk. PixlPush may require prior written approval, additional safeguards, an enterprise plan or a separate agreement before permitting use involving:\n\n• gambling, casino, betting or prize-based activities;\n\n• crypto-assets, initial coin offerings, high-risk investments or foreign exchange;\n\n• lending, debt collection, credit repair or financial promotions;\n\n• health, medical, pharmaceutical, weight-loss or therapeutic products;\n\n• alcohol, tobacco, vaping, CBD or other regulated products;\n\n• dating, adult, escort or sexually oriented services;\n\n• political, governmental or advocacy communications;\n\n• bulk recruiting, job boards or candidate solicitation;\n\n• lead-generation businesses or list-broker activities; and\n\n• any activity subject to heightened consent, licensing, carrier or platform rules.\n\nPixlPush may decline, restrict or suspend such use at its discretion where the Customer cannot demonstrate appropriate licensing, consent, recipient expectations, content controls, provider approval or legal safeguards. Approval for one campaign, Account or jurisdiction does not approve other campaigns, recipients, products or jurisdictions." },
    { heading: "5. Email, push and in-app communications", body: "Every marketing email must identify the sender accurately and contain a clear, functional unsubscribe mechanism where required. The Customer must honor unsubscribe and suppression requests without undue delay.\n\nEmail, mobile push and in-app messages must comply with the laws and rules of the recipient’s jurisdiction. The Customer is responsible for sender identification, frequency, timing, content, audience selection and recipient expectations.\n\nThe Customer must not send messages to suppressed, unsubscribed, blocked or permanently bounced recipients. PixlPush may enforce suppression lists, bounce controls, complaint controls and sending safeguards.\n\nFor mobile push and in-app communication, the Customer must obtain all required permissions before collecting device identifiers, push tokens, event data or notification preferences. Users must be able to withdraw or change notification preferences through the Customer’s app, website or device settings." },
    { heading: "6. Provider and platform requirements", body: "The Customer must comply with applicable requirements of:\n\n• Apple and Google developer and app-store programs;\n\n• Firebase and other push or SDK providers;\n\n• Amazon SES, SNS and other delivery providers;\n\n• payment processors and fraud-prevention providers;\n\n• hosting, analytics and integration providers;\n\n• network carriers and messaging platforms; and\n\n• any third-party service that the Customer connects to PixlPush.\n\nWhere a provider rule is stricter than this AUP, the stricter rule applies to the affected feature. PixlPush may pass through, update or enforce provider requirements without separately renegotiating these Terms where necessary to preserve access to the relevant infrastructure." },
    { heading: "7. AI features", body: "AI inputs, prompts, instructions and generated outputs are subject to the same content and legal restrictions as other Customer content.\n\nThe Customer must not use AI features to:\n\n• generate or distribute prohibited, illegal, deceptive or abusive content;\n\n• impersonate a person or organization deceptively;\n\n• generate spam, phishing or fraudulent communications;\n\n• evade privacy, consent, safety or content controls;\n\n• bypass, override or circumvent AI safety filters or usage guardrails;\n\n• use prompt injection, jailbreaking or similar methods to defeat security controls;\n\n• automate actions the Customer is not authorized to perform;\n\n• make high-impact decisions about individuals; or\n\n• send messages without required human or customer authorization.\n\nThe Customer is solely responsible for prompts, inputs, outputs, translations, audiences, actions and communications generated or initiated through AI features. AI output must be independently reviewed before publication, sending or business reliance.\n\nIf PixlPush later enables an external AI agent, MCP connection or similar tool that can create, modify, send or delete data, the Customer will be responsible for every action taken by that connected tool and must limit its access to the minimum data and actions necessary." },
    { heading: "8. Monitoring and risk signals", body: "PixlPush may assess technical and operational signals to protect the platform, providers and recipients, including:\n\n• bounce rates, complaint rates, unsubscribe rates and block rates;\n\n• sending volume, frequency, concurrency and unusual patterns;\n\n• delivery failures, provider feedback and domain reputation;\n\n• storage, compute, API and event usage;\n\n• security events, login anomalies and suspected account compromise;\n\n• recipient reports, abuse complaints and legal requests; and\n\n• content, link, domain and integration risk indicators.\n\nPixlPush may establish, publish or update service-specific thresholds and safeguards. A Customer may be suspended even if no single threshold is exceeded where the overall activity presents a material risk." },
    { heading: "9. Enforcement", body: "PixlPush may, without liability and with limited or no advance notice where reasonably necessary:\n\n• hold, delay, cancel or remove a message;\n\n• pause a campaign, journey or automation;\n\n• block a recipient, domain, link, device or integration;\n\n• disable sending, tracking, imports, exports or other features;\n\n• require additional information, verification or proof of consent;\n\n• freeze, restrict, suspend or terminate an Account;\n\n• report suspected illegal activity to providers or authorities; and\n\n• retain relevant evidence for security, legal, abuse, billing or claims purposes.\n\nPixlPush will provide notice and an opportunity to respond where reasonably practicable. Immediate action may be taken for serious violations, security risks, provider demands, legal requirements, fraud, spam, threats to deliverability or risks to other users.\n\nA suspension or termination for breach may result in loss of prepaid or unused fees as provided in the Terms of Service." },
    { heading: "10. Reporting abuse", body: "Abuse, security, privacy and rights-infringement reports should be submitted promptly through the contact channels listed in the PixlPush Legal Hub.\n\nCustomers must reasonably cooperate with investigations and provide relevant campaign, recipient, consent, domain, integration and account evidence." },
    { heading: "11. Changes", body: "PixlPush may update this AUP in response to legal, technical, security, provider, carrier, app-store or operational requirements. The current version will be published in the PixlPush Legal Hub." },
    { heading: "12. Contact", body: "Questions and abuse reports may be sent to contact@pixl-develop.com." },
  ] },
  "anti-spam": { title: "Anti-Spam Policy", description: "Permission, consent and sending requirements for PixlPush communications.", version: "1.0", effectiveDate: "13 October 2026", sections: [
    { heading: "Overview", body: "Version 1.0\n\nPublication version. This Policy applies to PixlPush communications and is updated when services, provider requirements, legal obligations or abuse patterns change.\n\nThis Anti-Spam Policy explains the rules that apply when a customer uses PixlPush to send email, mobile-push or in-app communications. It is intended to protect recipients, customers, PixlPush, delivery providers and the reliability of the platform.\n\nThis Policy forms part of the PixlPush Terms of Service and Acceptable Use Policy. It supplements the Privacy Policy and Data Processing Addendum where personal data and communication preferences are involved. If a conflict concerns Customer Personal Data processed on behalf of a customer, the DPA governs that processing to the extent of the conflict.\n\n1. What spam means\n\nSpam is an unwanted, unsolicited or unlawful communication sent through PixlPush. A message may be spam even if the sender has a business relationship with the recipient, the recipient’s address was publicly available, or a third party claims that the address was collected lawfully.\n\nA customer must have an appropriate legal basis and, where required, specific prior permission to send the relevant type of marketing communication to the relevant recipient through the relevant channel. The customer must be able to explain and, where required, demonstrate why the communication was lawful.\n\nPixlPush does not provide legal approval for a customer’s contact list, campaign, audience, consent record or sending practice. The customer remains responsible for the laws that apply to the sender, the customer, the recipient, the message and the channel.\n\n2. Scope\n\nThis Policy applies to:\n\n• email campaigns, transactional or service messages where PixlPush supports them, and automated email journeys;\n\n• mobile-push notifications and push journeys;\n\n• in-app messages and other customer-configured communications;\n\n• manual imports, SDK events, APIs, integrations and audience synchronisation;\n\n• messages generated or assisted by PixlPush AI;\n\n• sending domains, sender identities, reply-to addresses and delivery feedback;\n\n• unsubscribe, opt-out, push-block, suppression, bounce and complaint signals.\n\nThe customer is responsible for its own applications, websites, consent-management tools, app-store permissions and third-party systems connected to PixlPush.\n\n3. Contact data that may be used\n\nA customer may use a recipient address, device identifier, push token or other communication identifier only where the customer has the necessary rights and legal basis for the intended use.\n\nThe customer must keep contact data accurate, current and limited to what is necessary. The customer must maintain appropriate records of source, purpose, permission, preference, opt-out and suppression status where required by law.\n\nA customer must not assume that an email address, mobile device token, app installation, account registration or previous interaction is permission for every type of marketing message.\n\n4. Acceptable sources\n\nSubject to applicable law, acceptable sources may include:\n\n• a recipient’s direct, informed and appropriately recorded subscription to the relevant newsletter, product update or marketing topic;\n\n• an opt-in form where the relevant choice is clear, voluntary and not preselected;\n\n• a documented permission collected through an app, website, event or other direct customer interaction;\n\n• a customer relationship where the customer has independently assessed that a communication is permitted without prior marketing consent under the applicable law;\n\n• a service or transactional relationship where the message is genuinely necessary to provide, secure or administer the requested service.\n\nThe customer must not use a general acceptance of PixlPush’s Terms, a privacy notice, a cookie banner or an account registration as blanket permission for unrelated marketing.\n\n5. Prohibited contact sources\n\nThe following sources are prohibited unless the customer has independently obtained a new lawful basis and any required permission for the intended communication:\n\n• purchased, rented, leased, borrowed or appended lists;\n\n• lists obtained from a lead broker, data vendor or other third party merely because the vendor claims that consent exists;\n\n• scraped, harvested or copied addresses from websites, directories, social media or public records;\n\n• addresses collected for a different purpose or organization without a lawful compatibility assessment and any required notice;\n\n• addresses of people who have unsubscribed, objected, complained or requested suppression;\n\n• addresses or device identifiers obtained through malware, deception, unauthorized access or a security incident;\n\n• lists containing children’s data, sensitive data or other restricted data contrary to the Terms of Service or DPA;\n\n• lists where the customer cannot identify the source, purpose and permission status when that information is required.\n\nPublic availability of contact information does not by itself mean that the person agreed to receive marketing communications.\n\n6. Consent and preference management\n\nWhere consent is required, it must be freely given, specific, informed, unambiguous and capable of being demonstrated. A customer should use separate choices for materially different purposes or channels where required.\n\nCustomers must:\n\n• record the relevant consent or other legal basis;\n\n• identify the sender and the subject or purpose of the communication;\n\n• avoid preselected marketing choices where the law requires an active choice;\n\n• respect withdrawal, objection, unsubscribe, push-block and suppression requests;\n\n• avoid re-adding a suppressed recipient without a new lawful basis and any required permission;\n\n• keep preference data synchronized across relevant campaigns, journeys and integrations;\n\n• test that a withdrawal or suppression is applied before the next message is sent.\n\nPixlPush may process preference, unsubscribe, bounce, complaint and suppression signals to follow customer instructions, protect recipients and maintain deliverability.\n\n7. Email requirements\n\nEvery marketing email sent through PixlPush must, where required by applicable law:\n\n• identify the sender accurately;\n\n• use a valid sending domain and reply-to address;\n\n• avoid misleading headers, sender names, subject lines or links;\n\n• include legally required business or contact information;\n\n• include a clear and functional unsubscribe mechanism;\n\n• make the unsubscribe process easy to find and use;\n\n• stop further marketing messages to an unsubscribed recipient within the required period;\n\n• avoid re-subscribing the recipient without a new lawful basis and any required permission.\n\nA customer must not disguise an advertisement as a personal, security, service or transactional message. A message is not transactional merely because it contains a brand name or is sent through a product account.\n\n8. Mobile-push requirements\n\nBefore sending a marketing or promotional push notification, the customer must assess the permission and settings applicable to the recipient’s device, operating system, browser, application and jurisdiction.\n\nThe customer must:\n\n• provide appropriate notice about push communications;\n\n• obtain permission where required;\n\n• honor revoked permissions, disabled notifications, token invalidation and user preferences;\n\n• avoid sending to blocked, suppressed or invalid tokens;\n\n• identify the customer or product where required;\n\n• ensure that links, deep links and destinations are safe and accurately described;\n\n• use frequency and timing appropriate to the permission and context.\n\nPixlPush cannot guarantee delivery where a recipient is offline, a token is invalid, a platform rejects the message or the recipient has disabled notifications.\n\n9. In-app communications and journeys\n\nCustomers are responsible for the placement, timing, audience, frequency and content of in-app messages and automated journeys.\n\nA customer-configured journey may send or display communications automatically after activation according to its triggers, events, segments, schedules, suppression rules and other settings. The customer must test the journey before activation and monitor it after activation.\n\nThe customer must promptly pause or change a campaign or journey that produces unexpected, excessive, unlawful, harmful or misleading communications. An AI recommendation does not itself create permission or trigger a message; the customer remains responsible for activating and configuring the workflow.\n\n10. Required message content\n\nMessages must be accurate and must not:\n\n• impersonate another person, company or service;\n\n• conceal the sender or materially misstate the purpose of the message;\n\n• use deceptive subject lines, preview text, links or calls to action;\n\n• contain malware, malicious code or harmful attachments;\n\n• promote unlawful goods, services or activity;\n\n• direct recipients to deceptive, unsafe or unauthorized websites;\n\n• exploit a recipient’s vulnerability, distress or lack of knowledge;\n\n• make unsupported health, financial, legal, employment or performance claims;\n\n• use AI-generated content without appropriate human review.\n\nCustomers are responsible for checking generated translations, personalization, segmentation and recommendations before publication.\n\n11. List imports and integrations\n\nBefore importing a list or connecting an integration, the customer must assess:\n\n• the origin and collection method;\n\n• the identity and role of the original controller;\n\n• the purpose for which the data was collected;\n\n• the permission or other legal basis for the planned communication;\n\n• whether an information notice was provided;\n\n• whether an opt-out or suppression list must also be imported;\n\n• whether the integration may overwrite preferences or re-enable suppressed recipients;\n\n• whether the data includes restricted categories or people who must not be contacted.\n\nPixlPush may reject an import, pause an integration or require additional evidence where the source or sending permission is unclear.\n\n12. Monitoring and deliverability signals\n\nPixlPush may monitor technical and operational signals to protect recipients, customers, providers and the platform. Signals may include:\n\n• spam complaints and abuse reports;\n\n• hard and soft bounces;\n\n• invalid or unknown recipients;\n\n• unsubscribe and suppression activity;\n\n• provider blocks, throttling or reputation signals;\n\n• unusual sending volume, timing or audience growth;\n\n• repeated content, domain or account patterns associated with abuse;\n\n• phishing, malware, fraud or deception indicators;\n\n• unauthorized access or compromised credentials.\n\nPixlPush may use automated and human review proportionate to the risk. Monitoring does not guarantee that every unlawful or abusive campaign will be detected, and it does not transfer responsibility for the customer’s sending practices to PixlPush.\n\nPixlPush may establish internal risk thresholds and adjust them based on provider requirements, sending history, account type, recipient impact and current threat conditions. No fixed public percentage should be understood as a guaranteed safe or permitted level.\n\n13. Enforcement and account action\n\nWhere PixlPush identifies a credible risk or violation, it may:\n\n• request information or evidence about the contact source and permission;\n\n• require the customer to stop or modify a campaign;\n\n• hold, delay, reject or cancel messages;\n\n• block a recipient, address, device token, domain or sending identity;\n\n• enforce or update suppression and bounce controls;\n\n• restrict imports, integrations, API access or sending volume;\n\n• pause a campaign, journey or queue;\n\n• disable a feature or sending channel;\n\n• freeze or suspend an account;\n\n• terminate the Agreement where permitted by the Terms of Service;\n\n• notify a provider, customer, authority or affected person where required or appropriate.\n\nPixlPush may act without prior notice where necessary to protect recipients, prevent abuse, address a security incident, preserve deliverability or comply with law. Where reasonably practicable, PixlPush may explain the reason and request corrective information.\n\nA customer must not create another account, domain or integration to evade a restriction, suppression rule, sending limit or enforcement action.\n\n14. Evidence and customer cooperation\n\nPixlPush may ask the customer to provide information reasonably needed to assess sending activity, including:\n\n• the source and date of collection;\n\n• the purpose and type of permission;\n\n• consent or preference records;\n\n• the customer’s privacy and marketing notices;\n\n• campaign content, sender information and audience criteria;\n\n• bounce, complaint and unsubscribe handling;\n\n• relevant integration or SDK configuration.\n\nThe customer must respond accurately and promptly. It must not fabricate permission records, alter evidence after a complaint or continue sending to a disputed or suppressed recipient while an investigation is pending.\n\n15. Third-party providers and laws\n\nCustomers must comply with the laws applicable to their message, recipient and channel. Depending on the market, this may include EU ePrivacy rules and national implementations, UK PECR, U.S. CAN-SPAM, Canada’s CASL and other local requirements.\n\nThe customer is responsible for reviewing the terms and restrictions of third-party providers connected to its sending or push infrastructure. A provider’s acceptance of a message does not prove that the customer’s processing or communication is lawful.\n\n16. Reporting abuse\n\nSuspected spam, phishing, fraud, malware or misuse of PixlPush should be reported to:\n\ncontact@pixl-develop.com\n\nPlease include the message, sender, relevant URL and reason for the report where safe and lawful. Do not forward personal data or harmful attachments unnecessarily.\n\nCustomers must cooperate with reasonable abuse investigations and must promptly notify PixlPush if their account, credentials, sending domain, integration or API key may have been compromised.\n\n17. Relationship with other documents\n\nThis Anti-Spam Policy should be read with:\n\nTerms of Service\n\nAcceptable Use Policy\n\nPrivacy Policy\n\nData Processing Addendum\n\nAI Policy\n\nSecurity & Privacy\n\nResponsible Disclosure Policy\n\nThese documents should be kept consistent with the production controls, provider requirements and applicable law. The DPA governs processor processing of Customer Personal Data where applicable.\n\n18. Changes and publication\n\nPixlPush may update this Policy when its services, provider requirements, legal obligations, abuse patterns or technical controls change. The current version will be published in the PixlPush Legal Hub. Material changes may be communicated through the Legal Hub, account notices or other reasonable channels.\n\nThis Policy does not provide legal advice or guarantee that a customer’s campaign is lawful. Customers should obtain qualified advice for their own markets, recipients, products and communication practices.\n\n19. Restricted sectors and enhanced review\n\nPixlPush may require prior review, additional evidence or written approval for campaigns involving political or advocacy messaging, financial products, lending or debt collection, cryptocurrency or NFTs, gambling, dating or adult services, alcohol, tobacco, vaping or CBD, health or medical claims, weight-loss claims, lead generation, bulk recruiting, affiliate promotions or other uses that create elevated legal, fraud, abuse or delivery risk.\n\nPixlPush may prohibit or restrict a use even if it is lawful in a particular jurisdiction where it presents unacceptable risk to recipients, providers, infrastructure or the PixlPush platform. Approval for one campaign, account, provider or jurisdiction does not approve another.\n\n20. Fees and enforcement consequences\n\nIf PixlPush suspends, restricts or terminates an Account or service because of a breach of this Policy, the Terms of Service, the AUP, applicable law or provider rules, prepaid, unused or partially used fees are not refundable to the maximum extent permitted by law. Any discretionary refund, credit or goodwill payment is exceptional and does not create a continuing entitlement." },
  ] },
  "ai-policy": { title: "AI Policy", description: "How PixlPush uses and governs AI features and AI-assisted development.", version: "2.0", effectiveDate: "13 October 2026", sections: [
    { heading: "Overview", body: "Version 2.0\n\nPublication version. This Policy applies to AI features only when enabled and configured for the relevant PixlPush product or workspace.\n\nThis AI Policy explains how PIXLLOVE SOCIAL MEDIA APPLICATIONS DEVELOPMENT AND MANAGEMENT L.L.C. (“PixlPush”, “we”, “us” or “our”) uses and governs artificial intelligence (“AI”) in the PixlPush B2B SaaS platform. PixlPush provides customer-engagement, lifecycle-communication, analytics, email, mobile-push and in-app tools for business customers.\n\nThis Policy supplements the Terms of Service, Privacy Policy, Data Processing Addendum (“DPA”), Acceptable Use Policy and Security & Privacy materials. If a conflict concerns Customer Personal Data processed on behalf of a customer, the DPA controls to the extent of that conflict. Provider-specific services, purposes, regions and transfer safeguards are identified in the current Subprocessor & Provider List and applicable product documentation: https://docs.google.com/document/d/1K43OSFlRCMnM604G1h3RW61-jmBwlbybH8-b8Mi9W-U/edit" },
    { heading: "1. Scope and status", body: "This Policy applies to AI features made available in PixlPush, including AI agents, campaign and content assistance, performance analysis, journey recommendations, translation and localization. It applies whether the feature is used with email, mobile push, in-app messaging, campaigns, audiences, journeys, analytics or related workspace data.\n\nAI features are subject to the product configuration, plan, provider availability and permissions applicable to the relevant workspace. A control described in this Policy applies whenever the corresponding AI feature is enabled; provider-specific implementation details may be maintained in the current Subprocessor List, security materials and product documentation." },
    { heading: "2. Who operates PixlPush", body: "PixlPush is operated by:\n\nPIXLLOVE SOCIAL MEDIA APPLICATIONS DEVELOPMENT AND MANAGEMENT L.L.C.\n\nBuilding Name – ALSUAIDI / Plot Number 247-0 / Property Number 1F01\n\nDubai, United Arab Emirates\n\nEmail: contact@pixl-develop.com\n\nTelephone: +971 52 993 7054\n\nPixl-develop is a brand or development designation. It is not a separate PixlPush operator, contracting party or liable entity." },
    { heading: "3. Our approach to responsible AI", body: "PixlPush intends to apply the following principles:\n\nPurpose limitation. AI is used to provide a defined product or operational function, such as drafting content, analyzing engagement or recommending a journey change. AI is not introduced merely because it is technically available.\n\nTransparency. Customers should be able to understand when a feature uses AI, what type of information may be used, whether a result is a recommendation or an action, and which decisions remain with the customer.\n\nData minimization. AI requests should contain only the information reasonably necessary for the requested task. Users should not place unnecessary personal data, confidential information, credentials, secrets or sensitive data into prompts.\n\nHuman responsibility. AI outputs are assistance, not a substitute for customer judgment, legal review, marketing review, accessibility review, security review or other professional judgment. A customer remains responsible for content and settings it approves, publishes or activates.\n\nSecurity and confidentiality. AI data flows must use appropriate access controls, protected credentials and secure connections. Exact controls depend on the production architecture and provider configuration and must be verified before publication.\n\nAccountability. PixlPush will document relevant AI features, providers, purposes, data categories and restrictions. Material changes should be reviewed for privacy, security, contractual, product and regulatory consequences.\n\nRisk-based governance. PixlPush will assess the actual purpose and effect of an AI feature instead of relying only on its label. A feature that assists with marketing content is not automatically equivalent to a feature that makes decisions about a person’s access to employment, credit, healthcare, housing or essential services." },
    { heading: "4. PixlPush AI agents and features", body: "Depending on the plan and current product configuration, PixlPush may provide the following AI-assisted functions:\n\nMax – Growth Concierge. Max interprets a workspace user’s stated objective, helps coordinate available AI functions and recommends next steps. Max does not independently make contractual or legal decisions for PixlPush or the customer.\n\nBen – AI Performance Analysis. Ben can analyze relevant campaign, engagement, retention, churn, onboarding, paywall and performance information supplied through the workspace and provide observations or recommendations.\n\nNova – AI Campaign and Journey Optimizer. Nova can suggest lifecycle steps, triggers, timing, audience or segment logic, testing ideas and journey improvements based on the context supplied for the requested task.\n\nAnna – AI Email Creator. Anna can draft email content, subject lines, variants, personalization ideas and cross-sell or upsell concepts. The customer must review the result before using it.\n\nAI Translations. This feature can translate or localize email, mobile-push and in-app content. The customer remains responsible for meaning, cultural suitability, claims, accessibility, legal notices, opt-out instructions and the final language version.\n\nThe feature names, available models, input fields, output formats and supported channels may change. A customer should rely on the current interface, product documentation and applicable Order rather than assuming that every feature listed here is available on every plan." },
    { heading: "5. How an AI request is initiated", body: "PixlPush AI agents are currently designed to operate when an authorized workspace user actively invokes a feature, addresses an agent or submits an instruction. They are not intended to independently initiate background tasks without a user instruction.\n\nAn AI recommendation alone does not send an email, mobile push or in-app message. A customer-configured and activated campaign or journey may nevertheless send messages automatically according to the customer’s own rules, triggers, schedules, audience criteria, permissions and suppression logic. The customer is responsible for testing and monitoring that configuration.\n\nSome non-agent operational uses of AI may be introduced for security, abuse prevention, deliverability, support or service quality. Any such use must be assessed separately and described in the applicable privacy and contractual materials before it is activated for Customer Data." },
    { heading: "6. Optional and service-related AI use", body: "Some AI features are optional creative or analytical tools that a workspace user chooses to invoke. The user controls whether to submit a prompt or source material, subject to the fact that AI features are currently not customer-disableable as a general platform capability.\n\nAI may also be integrated into a workflow that the customer has chosen to configure, such as drafting a campaign or proposing journey logic. The customer controls whether to adopt the result and whether to activate a campaign or journey.\n\nPixlPush may restrict, pause or discontinue an AI feature when necessary for security, provider requirements, misuse prevention, legal compliance, product changes or technical reliability. Where a feature is essential to a paid service, any contractual change or notice obligation is handled under the Terms of Service or applicable Order." },
    { heading: "7. Information that may be processed", body: "Depending on the task and permissions, an AI request may include:\n\n• the authorized user’s prompt, instruction or conversation;\n\n• account, organization, workspace, role and configuration information;\n\n• campaign names, templates, subject lines, message text and content instructions;\n\n• audience, segment, journey, trigger, schedule and suppression context;\n\n• external user identifiers, event data and custom properties selected by the customer;\n\n• aggregated campaign, engagement, retention, churn, onboarding or performance information;\n\n• email, mobile-push and in-app content and relevant delivery context;\n\n• translation source text and the requested target language;\n\n• technical usage, error and security information needed to operate the feature;\n\n• AI-generated text, recommendations, classifications, translations or other outputs.\n\nCustom properties and event payloads are controlled by the customer. They may contain personal data even where the field was not designed specifically for personal data. PixlPush does not claim that every sensitive value can be detected or automatically blocked.\n\nUsers should provide only the minimum context needed for the requested result. Do not submit passwords, API keys, private keys, authentication tokens, payment-card details, confidential third-party information or personal data that is not necessary for the task." },
    { heading: "8. Roles and responsibility for Customer Data", body: "For Customer Data submitted through imports, SDKs, APIs, integrations, analytics, messaging or automations, PixlPush generally acts as the customer’s processor or service provider. The customer generally determines the purpose and means of processing its End User data and remains responsible for its controller or business obligations.\n\nThe customer must determine whether its use of an AI feature has a valid legal basis, requires notice or consent, involves profiling, creates an obligation to provide information to individuals, or is restricted by sector-specific or national law. The customer must maintain appropriate records and instructions and must ensure that its contract with PixlPush and the DPA cover the relevant processing.\n\nPixlPush acts as an independent controller for its own account, contract, billing, support, security, service administration, abuse prevention, CRM and legal-record processing. The Privacy Policy describes those activities. The parties do not become joint controllers merely because the customer uses PixlPush or invokes an AI feature." },
    { heading: "9. Sensitive data, children and prohibited inputs", body: "Customers must not submit special-category or similarly sensitive personal data, data about children or minors, criminal-offence data, precise or continuous location data or highly sensitive financial data to PixlPush AI features unless PixlPush has first approved the use in writing after separate legal and technical review and additional safeguards have been agreed.\n\nThis is a contractual restriction and not a representation that the platform can technically identify every prohibited input. Customers must filter or minimize their data before sending it to PixlPush and must not use an AI feature to avoid a legal restriction that would apply to the underlying data.\n\nIf a customer believes that a particular use may involve health, biometric, genetic, racial or ethnic, political, religious, sexual, criminal, child-related or similarly sensitive data, it must stop the proposed use and contact PixlPush before submitting the data." },
    { heading: "10. Gemini and external AI services", body: "PixlPush uses Google AI Studio and the Gemini API as its designated external AI provider for PixlPush AI functions. PixlPush does not use Vertex AI for the AI functions described in this Policy.\n\nThe exact service, account, billing status, model, region, logging configuration, retention setting and enabled features must be confirmed in the production project. The Privacy Policy, DPA and Subprocessor List must identify the applicable service and data flow.\n\nGoogle’s terms distinguish paid and unpaid services and describe different data-use conditions. For customers and API clients in the European Economic Area, Switzerland or the United Kingdom, the applicable Google terms may require the use of paid services. PixlPush must therefore verify the production billing account, applicable Google data-processing terms and relevant account configuration before production processing of Customer Personal Data through Gemini.\n\nThe official Gemini API terms are available at:\n\nhttps://ai.google.dev/gemini-api/terms\n\nThe existence of a paid account does not by itself prove that a specific retention, logging, region or zero-data-retention setting is active. PixlPush must not promise EU-only processing, zero retention or the absence of provider safety logging unless the applicable provider documentation and production configuration support that statement." },
    { heading: "11. Customer Data and model training", body: "PixlPush does not intend to use Customer Data, End User data, campaign content, prompts, instructions or AI outputs to train general-purpose AI models. This statement describes PixlPush’s own use of the data.\n\nIt does not automatically describe how an external provider handles data under every service tier, account type or configuration. Provider terms, data-processing terms, logging, abuse monitoring, support access, retention and regional processing must be reviewed for the actual production service.\n\nBefore enabling customer-data AI processing, PixlPush will configure the applicable provider service under the selected commercial terms, apply the documented data-processing and transfer safeguards, disable optional model-improvement sharing where required by this Policy, and document applicable provider logging, retention and deletion settings." },
    { heading: "12. AI output, accuracy and intellectual property", body: "AI outputs may be incomplete, inaccurate, outdated, ambiguous, biased, unsuitable for a particular audience or inconsistent with the customer’s brand and legal obligations. AI may generate content that resembles content generated for another user or that contains errors or unsupported claims.\n\nThe customer must review AI output before publishing or using it, including:\n\n• factual accuracy, prices, dates, product descriptions and legal claims;\n\n• audience selection, segmentation and personalization;\n\n• translation quality, cultural context and accessibility;\n\n• sender identity, unsubscribe instructions and consent language;\n\n• links, tracking parameters, attachments and destination pages;\n\n• intellectual-property, publicity, confidentiality and third-party rights;\n\n• potential discrimination, manipulation, deception, safety or reputational harm;\n\n• whether the output is appropriate for email, mobile push or in-app presentation.\n\nPixlPush does not guarantee that an AI output is original, non-infringing, accurate, suitable or available for unrestricted commercial use. The customer is responsible for deciding whether to use, edit, publish or delete an output and for retaining evidence of any human review required by its own policies or applicable law." },
    { heading: "13. Email, mobile push and in-app communications", body: "AI can help draft or optimize messages, but it does not transfer responsibility for the communication to PixlPush. The customer remains responsible for the recipient, sender, content, timing, targeting, frequency, links, claims, attachments, permissions and applicable notices.\n\nFor email, the customer must review sender identity, required commercial information, unsubscribe mechanisms, suppression lists, deliverability risks and applicable electronic-marketing rules.\n\nFor mobile push, the customer must review device and application permissions, push-token status, notification content, deep links, frequency, operating-system requirements and user-level opt-outs.\n\nFor in-app communications, the customer must review where and when the message appears, whether the user has been appropriately informed, whether the message is accessible, and whether the targeting or content is appropriate for the product context.\n\nAn AI-generated draft must not be treated as evidence that a message is lawful. The customer must not use AI to generate spam, phishing, deceptive sender information, unlawful profiling, manipulative content or messages to recipients who have unsubscribed or otherwise opted out." },
    { heading: "14. Journeys, automation and recommendations", body: "AI may recommend a journey structure, event trigger, segment, timing rule, experiment or message variant. The recommendation does not itself create a legal basis, permission, consent record or contractual authorization.\n\nIf the customer accepts a recommendation and activates a journey, the journey may operate automatically according to the customer’s configuration. The customer must test entry and exit criteria, frequency caps, suppression rules, failure handling, pause behavior and reactivation behavior before activation and should monitor the results after activation.\n\nThe customer must promptly pause or change a journey that produces unexpected, excessive, unlawful or harmful communications. PixlPush may pause or stop AI-assisted campaigns, journeys or queued messages when reasonably necessary to address security, abuse, deliverability, provider, legal or operational risks." },
    { heading: "15. Analytics, personalization and profiling", body: "PixlPush AI may analyze events, campaign performance, audience attributes or engagement signals to provide recommendations, summaries, translations or optimization ideas. The customer determines how it uses those results and whether the resulting processing constitutes profiling.\n\nThe customer must not use PixlPush AI to make or facilitate decisions based solely on automated processing that produce legal or similarly significant effects on individuals. Prohibited examples include decisions about credit, insurance, employment, housing, education, healthcare eligibility or access to essential services.\n\nThe customer must not use AI outputs to discriminate unlawfully, infer sensitive characteristics without a lawful basis, target vulnerable people improperly, manipulate individuals, or conceal a material automated decision. If a customer plans to use personalization, scoring or segmentation in a way that may materially affect individuals, it must carry out its own legal assessment and provide any required notice or rights." },
    { heading: "16. AI safety and prohibited use", body: "The customer and its authorized users must not use PixlPush AI to:\n\n• create or distribute spam, phishing, malware, fraud or deceptive content;\n\n• impersonate a person, organization or sender;\n\n• evade suppression, unsubscribe, consent, authentication or security controls;\n\n• generate unlawful discrimination, harassment, threats or abusive targeting;\n\n• make prohibited high-impact decisions or unlawful profiling;\n\n• process prohibited sensitive data or children’s data without prior written approval;\n\n• generate content that infringes intellectual-property, privacy, publicity or confidentiality rights;\n\n• bypass provider safety controls or attempt to extract, replicate or reverse engineer an external model;\n\n• overload, probe, scan or disrupt PixlPush or a provider;\n\n• create messages intended to manipulate, deceive or exploit recipients;\n\n• use AI outputs as medical, legal, financial, employment or other professional advice without qualified review.\n\nPixlPush may investigate suspected misuse using proportionate technical and human review. It may refuse a request, filter or hold content, restrict an AI feature, pause a campaign or journey, block a recipient or domain, freeze an account or terminate access where permitted by the Agreement and applicable law." },
    { heading: "17. Human oversight and operational controls", body: "A responsible person at the customer must review AI-generated content and recommendations before publication or activation where the result could affect recipients, customer communications, contractual commitments, compliance, reputation or service access.\n\nHuman review should be meaningful rather than a purely formal click. The reviewer should have enough context, authority and competence to identify factual, legal, security, accessibility and audience risks.\n\nPixlPush’s internal governance should include an inventory of AI features, documented purposes, data-flow review, provider review, access restrictions, change review, incident handling and periodic reassessment. The implementation status of these controls must be confirmed before PixlPush describes them as fully operational." },
    { heading: "18. Security, access and confidentiality", body: "AI requests should be transmitted through secured service connections and handled through access controls appropriate to the feature. API credentials and provider keys must be protected as secrets and must not be exposed to customers or included in generated content.\n\nAI context should be limited to the workspace, project, user permissions and task for which it was requested. PixlPush should prevent an AI feature from receiving unrelated tenant data or information outside the authorized context. Tenant separation, authorization checks, prompt construction, logging and redaction behavior must be verified against the production implementation.\n\nAI-generated content is not automatically trustworthy. Generated code, configuration, links, queries or instructions must be reviewed before execution. Users must not execute AI-generated commands or upload AI-generated files without appropriate security review." },
    { heading: "18A. Internal AI-Assisted Development", body: "PixlPush may use approved AI-assisted development tools, including ChatGPT and Codex where approved, for source-code development, documentation, debugging and database-schema assistance. These tools are used for internal development purposes and are not part of the Customer-facing AI features described in this Policy.\n\nEmployees must not submit Customer Personal Data, production database exports, identifiable query results, credentials, API keys, environment files, private keys, access tokens or confidential customer information to external AI tools. Database-related assistance must use schema-only information, synthetic data or appropriately anonymized examples unless a separate provider, security and data-processing review has been completed.\n\nQuery text must also be reviewed before submission because a query may contain email addresses, external user identifiers, device identifiers or other personal data. Query results, logs and screenshots must be treated as potentially sensitive information and must not be shared with an external AI tool unless the relevant use has been specifically approved.\n\nPixlPush should maintain internal controls for approved AI tools, account types, cloud or local execution, access permissions, employee AI literacy, retention settings, incident reporting and data minimization. Internal AI-assisted development must not be used to bypass production access controls or expose secrets.\n\nThe use of internal AI development tools does not make their providers subprocessors for Customer Data unless Customer Data is actually disclosed to or processed by those providers. If that occurs, the relevant provider, data flow, contractual safeguards, international transfer basis and customer-facing documentation must be reviewed and updated before the processing continues." },
    { heading: "19. Logging, retention and deletion", body: "PixlPush may retain limited AI prompts, context, outputs, audit events, error information or provider references where necessary to provide the feature, troubleshoot failures, protect security, investigate abuse, comply with law or establish and defend claims.\n\nThe precise retention period for AI conversations, prompts, outputs, provider logs and support records has not yet been finalized. PixlPush must define those periods in its internal retention schedule and align them with the Privacy Policy, DPA, backup process and provider settings.\n\nFor Customer Data, deletion and return follow the DPA and customer instructions, subject to lawful retention exceptions. The intended frozen and inactive-account rule is described in the Terms of Service and Privacy Policy. The planned 12-month operational retention period plus a further 30-day deletion-notice period is a product rule, not evidence that automated deletion jobs or provider backup overwrites are already operating." },
    { heading: "20. International transfers and provider access", body: "PixlPush is operated from the United Arab Emirates. AI processing may involve Google infrastructure, support access or service locations outside the EEA, United Kingdom or Switzerland. EU-region processing is used only where the particular Google service and production configuration support and select it.\n\nPixlPush must document the provider, service, data categories, processing purpose, region, support access, onward transfers and applicable transfer mechanism for each AI data flow. Depending on the parties, locations and applicable law, this may require an adequacy decision, approved contractual safeguards, a UK addendum, Swiss adaptations, supplementary measures or a transfer impact assessment.\n\nNo statement in this Policy should be read as a promise that all AI data remains in the EU or that a particular transfer safeguard has been completed until the relevant contracts and production configuration have been checked." },
    { heading: "21. Customer responsibilities", body: "Each customer must:\n\n• use AI only for lawful business purposes;\n\n• provide lawful instructions and ensure that its data sources and integrations are authorized;\n\n• give individuals the notices required for SDKs, tracking, personalization, messaging, profiling and AI-related processing;\n\n• obtain and record consent where required and honor withdrawals, unsubscribes, push blocks and suppression requests;\n\n• minimize prompts and avoid unnecessary personal or confidential data;\n\n• review outputs before use and monitor activated campaigns and journeys;\n\n• assess copyright, trademark, privacy, confidentiality, accessibility and consumer-protection risks;\n\n• avoid prohibited sensitive data, children’s data and high-impact decisions;\n\n• cooperate with reasonable security, abuse and compliance investigations;\n\n• notify PixlPush if it discovers that AI processing is being used outside the agreed purpose or instructions." },
    { heading: "22. Provider changes and new AI features", body: "PixlPush may add, replace or discontinue AI models, providers or features. Before a material change is placed into production, PixlPush should assess:\n\n• the new provider’s terms, DPA, security documentation and data-use conditions;\n\n• the data categories and context sent to the provider;\n\n• region, support access, logging and retention;\n\n• subprocessors and transfer mechanisms;\n\n• security, privacy, bias, accessibility and misuse risks;\n\n• whether the Privacy Policy, DPA, Subprocessor List, Terms or AUP require updates;\n\n• whether customer notice, consent, contractual approval or a new risk assessment is required.\n\nA new AI feature must not be described as covered by this Policy merely because it uses a similar model. Its actual purpose and data flow must be reviewed." },
    { heading: "23. Complaints, incidents and contact", body: "Questions about PixlPush’s AI processing or a suspected AI-related privacy or security incident should be sent to contact@pixl-develop.com. Do not include passwords, API keys, private keys or unnecessary personal data in an initial report.\n\nIf an incident affects Customer Personal Data, PixlPush will assess and respond under the DPA and applicable law and will notify the affected customer as required by the agreed incident process. Customers must promptly notify PixlPush of suspected misuse, unauthorized AI access, compromised credentials or unlawful processing." },
    { heading: "24. Related documents and final review status", body: "This Policy should be read with the Terms of Service, Privacy Policy, Data Processing Addendum, Acceptable Use Policy, Security & Privacy, Software Lifecycle Policy, Responsible Disclosure Policy and Subprocessor List.\n\nAI deployment requirements:\n\n• the exact production Gemini service, billing status and applicable Google terms;\n\n• whether any AI Studio or Gemini logging, storage, grounding or file features are enabled;\n\n• the actual model, region, provider access and retention configuration;\n\n• tenant authorization, prompt construction, redaction and audit logging;\n\n• AI conversation and output retention periods;\n\n• deletion from active systems and provider backups;\n\n• the current Subprocessor List and transfer documentation;\n\n• whether any future AI feature is optional, service-related or operational;\n\n• the final legal assessment under applicable UAE, EU, UK, Swiss, U.S. and other relevant laws.\n\nThis Policy is effective from the date stated above. PixlPush will update it when AI features, providers, applicable law or material data flows change. Customers remain responsible for their own lawful configuration, notices, permissions and review of AI outputs." },
    { heading: "25. Related document links", body: "The following documents are part of the PixlPush legal and compliance set and should be read together with this Policy:\n\nTerms of Service\n\nPrivacy Policy\n\nData Processing Addendum (DPA)\n\nAcceptable Use Policy\n\nSecurity & Privacy\n\nSoftware Lifecycle Policy\n\nResponsible Disclosure Policy\n\nCookie Policy\n\nGDPR & Privacy Compliance Information\n\nThe applicable external AI terms should also be reviewed for the production service:\n\nGoogle Gemini API Additional Terms\n\nThese links are provided for convenience and must be kept aligned with the current versions, publication status and production configuration. If a linked document conflicts with this Policy, the applicable contractual order of precedence and the DPA govern as described in the relevant documents.\n\nGoogle Cloud Privacy Notice." },
  ] },
  "security": { title: "Security & Privacy", description: "PixlPush security practices, safeguards and trust information.", version: "2.0", effectiveDate: "13 October 2026", sections: [
    { heading: "Overview", body: "Version 2.0\n\nThis Security & Privacy overview describes the principal technical and organizational measures PixlPush uses to protect the confidentiality, integrity, availability and lawful processing of data. It supplements the Terms of Service, Privacy Policy and DPA.\n\nNo online service can guarantee absolute security. Customers remain responsible for protecting credentials, configuring permissions and using the Services lawfully." },
    { heading: "1. Security governance", body: "PixlPush maintains security responsibilities, access procedures, change controls, incident processes and provider reviews appropriate to the Services.\n\nSecurity risks are considered in product development, infrastructure changes, integrations, data flows and new features, including AI-assisted features.\n\nPersonnel and contractors with access to confidential information are subject to confidentiality obligations and access restrictions." },
    { heading: "2. Tenant separation and data handling", body: "Customer workspaces, projects and access permissions are logically separated. Requests and data access are scoped to the relevant Customer, workspace and project.\n\nCustomer Data is processed only to provide, secure, support and maintain the Services, in accordance with the Customer’s instructions and the DPA.\n\nProduction data is not intentionally used in development or testing environments. Test and development work should use synthetic, anonymized or otherwise non-production data." },
    { heading: "3. Identity and access", body: "PixlPush uses authentication, authorization and role-based access controls to restrict access to Accounts, workspaces, projects and administrative functions.\n\nAccess is granted according to business need and should be removed when no longer required. Administrative and security-relevant actions may be logged for accountability, investigation and abuse prevention.\n\nCustomers must protect their credentials, limit Authorized Users, review permissions and promptly report suspected compromise." },
    { heading: "4. Encryption and secrets", body: "Data transmitted between Customers, users, applications and PixlPush services is protected using industry-standard transport encryption where supported.\n\nSensitive credentials, API keys, tokens and provider secrets are stored and handled using protected secret-management mechanisms. Secrets must not be placed in source code, public repositories, browser-visible configuration or customer messages.\n\nWhere supported by the relevant provider and service, stored data and backups are protected using encryption at rest and provider security controls." },
    { heading: "5. Secure development", body: "PixlPush applies secure development practices appropriate to the product, including code review, dependency management, security testing, change control, error handling and vulnerability remediation.\n\nThird-party packages, APIs, SDKs and infrastructure are reviewed as part of ordinary engineering and operational processes. Security fixes may require emergency releases or feature changes." },
    { heading: "6. Monitoring and incident response", body: "PixlPush monitors operational, authentication, access, delivery, abuse and security signals appropriate to the Services.\n\nWe maintain procedures for investigating suspected incidents, containing unauthorized activity, assessing impact, preserving evidence, remediating vulnerabilities and communicating with affected Customers or authorities where required.\n\nWhere PixlPush acts as processor, personal-data breach notifications are handled in accordance with the DPA and applicable law." },
    { heading: "7. Availability, backups and deletion", body: "PixlPush uses hosting, database, storage, deployment and delivery providers to operate the Services. Availability may be affected by maintenance, provider outages, networks, devices, operating systems, carriers and events outside PixlPush’s reasonable control.\n\nOperational data is retained and deleted in accordance with the Privacy Policy, Terms of Service and DPA.\n\nBackups are isolated from active systems, access-restricted and overwritten or securely deleted according to the applicable backup cycle. The target deletion rule for deleted primary data is no later than 30 days after primary deletion, subject to lawful retention exceptions and provider recovery cycles." },
    { heading: "8. Providers and regions", body: "Depending on the feature, PixlPush uses providers including Supabase, Vercel, Cloudflare, Google Cloud, Firebase, BigQuery, Google Analytics, Google Ads, Meta, Google Gemini, Amazon SES, Amazon SNS, Stripe, CookieYes and HubSpot.\n\nProvider roles, locations, transfer mechanisms and relevant data categories are described in the Privacy Policy, DPA and Subprocessor List.\n\nThe primary production database and storage configuration targets an EU region where supported. Email delivery is configured for AWS eu-north-1. Website hosting and edge services may use globally distributed infrastructure." },
    { heading: "9. Security reports", body: "Suspected vulnerabilities should be reported through the PixlPush Responsible Disclosure Policy.\n\nSecurity and privacy questions may be sent to contact@pixl-develop.com. Customers should not send passwords, API keys, credentials, database exports or unnecessary personal data in an initial report." },
    { heading: "10. Certifications and assurance", body: "PixlPush does not claim SOC 2, ISO 27001, ISO 27701, HIPAA, PCI DSS or other certification unless a current, applicable independent certificate or contractual assurance supports the specific claim.\n\nSecurity questionnaires, audit information and additional assurance materials may be provided to eligible Customers subject to confidentiality, scope, availability and reasonable administrative requirements." },
    { heading: "11. Service levels", body: "An SLA applies only where expressly agreed in an Order or separate written agreement. This overview does not create an uptime, response-time, support or recovery-time guarantee.\n\nA status page or incident communication channel may be used to communicate operational events when available." },
    { heading: "12. Customer responsibilities", body: "Customers must:\n\n• use strong, unique credentials and protect API keys;\n\n• restrict Authorized Users and review access regularly;\n\n• configure domains, integrations, SDKs and permissions correctly;\n\n• keep applications, SDKs and integrations supported and updated;\n\n• avoid submitting unnecessary sensitive data;\n\n• maintain independent exports and backups where needed;\n\n• follow the Terms, AUP, Privacy Policy and DPA; and\n\n• notify PixlPush promptly of suspected compromise, abuse or unauthorized access." },
    { heading: "13. Changes", body: "PixlPush may update this overview when security practices, infrastructure, providers, legal requirements or product features change. The current version will be published in the Legal Hub." },
    { heading: "14. Contact", body: "Security and privacy reports may be sent to:\n\ncontact@pixl-develop.com" },
  ] },
  "gdpr-compliance": { title: "GDPR & Privacy Compliance", description: "Privacy roles, rights, retention and international processing information.", version: "1.0", effectiveDate: "13 October 2026", sections: [
    { heading: "Overview", body: "Version 1.0\n\nPublication version. This overview is informational and supplements the Privacy Policy, DPA, Terms of Service and Security & Privacy documents; it is not a certification or independent legal opinion." },
    { heading: "1. Our approach", body: "PixlPush is a B2B SaaS platform designed to support transparent data processing. Compliance depends on the actual configuration, customer instructions, legal bases and practices of each party." },
    { heading: "2. Roles", body: "PixlPush generally acts as controller for account, contract, billing, support, security and abuse-prevention data. For end-user data imported, collected through SDKs or sent through integrations, PixlPush generally acts as processor. The customer remains controller for its end users and content, subject to the specific processing involved." },
    { heading: "3. Legal bases and consent", body: "Depending on the purpose and applicable law, processing may rely on contract performance, legal obligations, legitimate interests or consent. Cookie, marketing and tracking consent must be collected separately and for the relevant purpose. Accepting the Terms is not blanket consent to marketing or tracking." },
    { heading: "4. Data subject rights", body: "Where applicable, rights may include access, rectification, erasure, restriction, portability and objection. End users should generally contact the relevant customer first. PixlPush assists customers under the DPA. Requests about PixlPush account or business data can be sent to contact@pixl-develop.com." },
    { heading: "5. Providers and regions", body: "Depending on the feature, providers may include Supabase, Vercel, Cloudflare, Google Cloud, Firebase, BigQuery, Google Analytics, Google Ads, Meta, Gemini / Google AI Studio, AWS SES/SNS and Stripe. EU regions are used where supported by the specific service and configuration. Other processing may occur globally or outside the EEA." },
    { heading: "6. Retention", body: "Frozen and non-reactivated accounts follow the 12-month operational retention period, followed by a final notice and an additional 30 days before deletion, subject to lawful exceptions. During a frozen status, no new users or tracking events are stored and no new email or push messages are sent; billing, payment, export and deletion remain available. Backups are intended to be overwritten within 30 days after primary deletion, subject to technical verification." },
    { heading: "7. Security", body: "Planned and implemented safeguards may include access controls, two-factor authentication, encryption in transit, role controls, audit logs, backups and recovery, patch management and incident response. External testing is described only when completed and verified. PixlPush does not claim SOC 2, ISO 27001 or ISO 27701 certification without a valid independent certificate." },
    { heading: "8. Documents", body: "The PixlPush legal documentation includes the Privacy Policy, Terms of Service, Cookie Policy, DPA, AUP, AI Policy, Security & Privacy, Software Lifecycle Policy, Responsible Disclosure Policy and Subprocessor List.\n\nThis overview does not replace the full contractual documents or legal review." },
  ] },
  "dpa": { title: "Data Processing Addendum", description: "Controller and processor terms for customer data processed through PixlPush.", version: "1.1", effectiveDate: "13 October 2026", sections: [
    { heading: "Overview", body: "Version 1.1\n\nThis DPA establishes the data-protection, security, international-transfer, retention and deletion baseline that PixlPush will implement and maintain for production processing of Customer Personal Data. PixlPush will operate the Services in accordance with this DPA, the Agreement and applicable Data Protection Laws.\n\nThis Data Processing Addendum (“DPA”) forms part of the Terms of Service or other written subscription agreement between the customer identified in the applicable order, account or agreement (“Customer”) and PIXLLOVE SOCIAL MEDIA APPLICATIONS DEVELOPMENT AND MANAGEMENT L.L.C., the sole operator and contracting party for PixlPush (“PixlPush”). This DPA applies when and to the extent PixlPush processes Personal Data on behalf of Customer in providing the Services. It applies to Customer’s use of the Services whether or not a particular data subject or Customer is located in the EEA, United Kingdom or Switzerland, subject to applicable law.\n\nIf this DPA conflicts with the Terms of Service concerning the processing of Customer Personal Data, this DPA controls to the extent of the conflict. The Terms of Service continue to govern other matters. The DPA is accepted electronically or in writing by an authorised representative of the Customer and PixlPush and is linked to the applicable customer account or order." },
    { heading: "1. Definitions", body: "1.1. “Affiliate” means an entity that directly or indirectly controls, is controlled by, or is under common control with a party. An Affiliate may use the Services only if Customer authorizes it and remains responsible for its compliance with the Agreement. No Affiliate is a party to this DPA unless it signs an applicable order or accession.\n\n1.2. “Agreement” means the Terms of Service, applicable order form or subscription agreement, this DPA, and any schedules expressly incorporated into them.\n\n1.3. “Applicable Data Protection Law” means privacy and data-protection laws that apply to a party’s Processing of Personal Data under the Agreement, including, where applicable, the GDPR, UK GDPR, the UK Data Protection Act 2018, the Swiss Federal Act on Data Protection, the UAE Federal Decree-Law No. 45 of 2021 on the Protection of Personal Data, and applicable U.S. state privacy laws.\n\n1.4. “Customer Personal Data” means Personal Data Processed by PixlPush on behalf of Customer through the Services, excluding Account Data and other information PixlPush processes as an independent Controller for its own purposes.\n\n1.5. “Data Protection Laws” means Applicable Data Protection Law as it applies to the Processing in question.\n\n1.6. “Data Subject” means the identified or identifiable natural person to whom Personal Data relates.\n\n1.7. “GDPR” means Regulation (EU) 2016/679. “UK GDPR” means the GDPR as it forms part of the law of the United Kingdom, together with the UK Data Protection Act 2018 and applicable regulations. “Swiss FADP” means the Swiss Federal Act on Data Protection of 25 September 2020 and its implementing ordinance.\n\n1.8. “Personal Data” and “Processing” have the meanings given under the applicable Data Protection Laws. “Process” and “Processed” are interpreted accordingly.\n\n1.9. “Processor” means a person or entity that Processes Personal Data on behalf of a Controller. “Controller” means the person or entity that determines the purposes and essential means of Processing. “Business”, “Service Provider” and similar terms have the meaning assigned by the relevant applicable law.\n\n1.10. “Services” means PixlPush’s B2B SaaS products and related features made available under the Agreement, including imports, SDKs, APIs, audience management, segmentation, email, mobile push and in-app communications, journeys and automations, analytics, exports, deletion tools and AI-assisted functions.\n\n1.11. “Subprocessor” means a third party engaged by PixlPush to Process Customer Personal Data on behalf of Customer in connection with the Services.\n\n1.12. “Security Incident” means a confirmed breach of security leading to accidental or unlawful destruction, loss, alteration, unauthorized disclosure of, or access to Customer Personal Data in PixlPush’s or its Subprocessor’s possession or control. A failed attempt or activity that does not compromise Customer Personal Data is not by itself a Security Incident.\n\n1.13. “Standard Contractual Clauses” or “SCCs” means the European Commission’s standard contractual clauses adopted by Commission Implementing Decision (EU) 2021/914, as amended or replaced." },
    { heading: "2. Scope, term and relationship of the parties", body: "2.1. This DPA governs PixlPush’s Processing of Customer Personal Data as Processor or Service Provider. It does not govern Personal Data for which PixlPush acts as an independent Controller, including account administration, billing, PixlPush’s own customer relationship management, support administration, service security, abuse prevention and legal records. PixlPush’s Privacy Policy describes those controller activities.\n\n2.2. This DPA takes effect when Customer accepts or otherwise agrees to the Agreement and remains in effect for as long as PixlPush Processes Customer Personal Data under the Agreement. Termination of this DPA does not end the Agreement unless the Agreement is also terminated.\n\n2.3. Where Customer acts as a Processor for another Controller, Customer remains responsible for its obligations to that Controller. The parties will apply the SCC module appropriate to their actual roles, including Module 3 where Customer is a Processor and PixlPush is a Subprocessor.\n\n2.4. Nothing in this DPA creates a joint-controller arrangement. If a particular feature or Processing activity makes the parties joint Controllers under applicable law, the parties will document that arrangement separately before that activity begins." },
    { heading: "3. Roles and Customer’s obligations", body: "3.1. Customer determines the purposes and means of Processing Customer Personal Data and acts as Controller or Business, except where Customer itself acts as Processor for another Controller. PixlPush acts as Processor or Service Provider and Processes Customer Personal Data only as described in this DPA, the Agreement, the applicable product configuration and Customer’s documented lawful instructions.\n\n3.2. Customer is responsible for:\n\n(a) identifying and documenting a lawful basis for each Processing activity and any required condition for processing special-category data;\n\n(b) providing clear and legally sufficient privacy notices to Data Subjects, including disclosures about SDKs, cookies or similar technologies, profiling, messaging, AI use, recipients and international transfers where required;\n\n(c) collecting, recording and honoring permissions, consents, objections, opt-outs, unsubscribes and device-level push preferences;\n\n(d) determining that its data sources, imports, integrations, audiences, event collection, campaign content, senders and communication schedules are lawful;\n\n(e) responding to Data Subject requests and complaints, subject to PixlPush’s assistance under this DPA;\n\n(f) configuring the Services and its integrations in a manner consistent with its instructions and legal obligations;\n\n(g) protecting Customer credentials, API keys, SDK secrets, administrator accounts, devices and networks;\n\n(h) ensuring that Authorized Users are permitted to access Customer Personal Data and are bound by confidentiality obligations;\n\n(i) conducting any required legitimate-interest assessment, DPIA, transfer assessment or consultation with a supervisory authority; and\n\n(j) ensuring that Customer Personal Data is accurate, relevant, limited to what is necessary and not retained longer than required.\n\n3.3. Customer represents that it has the rights and authority necessary to provide Customer Personal Data to PixlPush and to authorize the Processing and transfers described in the Agreement and this DPA. Customer shall not direct PixlPush to Process Personal Data unlawfully.\n\n3.4. Customer shall not submit through the Services special-category Personal Data, criminal-offence data, precise or continuous location data, highly sensitive financial data, or Personal Data relating to children or minors unless PixlPush has first given written approval after legal and technical review and the parties have agreed on additional safeguards. Customer shall filter such data before it is sent. PixlPush does not undertake to identify, classify or remove such data automatically.\n\n3.5. Customer shall not use the Services to make or facilitate a decision based solely on automated Processing that produces legal or similarly significant effects, or for unlawful discrimination, high-risk profiling or decisions concerning credit, insurance, employment, education, housing, healthcare or eligibility for essential services. Customer remains responsible for assessing profiling and AI rules applicable to its use." },
    { heading: "4. PixlPush’s Processing obligations", body: "4.1. PixlPush shall:\n\n(a) Process Customer Personal Data only on documented instructions from Customer, including instructions concerning international transfers, unless applicable law requires otherwise. If law requires processing beyond the instructions, PixlPush will inform Customer before processing unless legally prohibited;\n\n(b) inform Customer without undue delay if PixlPush reasonably believes an instruction infringes Data Protection Laws, without being required to provide legal advice;\n\n(c) ensure that persons authorized to Process Customer Personal Data are bound by appropriate confidentiality obligations;\n\n(d) implement and maintain the technical and organizational measures described in Annex 2, subject to the status and verification qualifications stated there;\n\n(e) engage Subprocessors only as permitted by Section 6;\n\n(f) taking into account the nature of Processing, assist Customer through appropriate technical and organizational measures, insofar as reasonably possible, to respond to Data Subject requests;\n\n(g) assist Customer in meeting its obligations under Articles 32 to 36 GDPR or corresponding applicable law, taking into account the nature of Processing and information available to PixlPush;\n\n(h) at Customer’s choice, delete or return Customer Personal Data after the end of the Services, subject to Section 9 and applicable law;\n\n(i) make available information reasonably necessary to demonstrate compliance with this DPA and permit audits as described in Section 10; and\n\n(j) notify Customer of a Security Incident in accordance with Section 8.\n\n4.2. PixlPush shall not:\n\n(a) sell Customer Personal Data;\n\n(b) retain, use or disclose Customer Personal Data outside the direct business relationship with Customer or the purposes stated in the Agreement, except as permitted or required by law;\n\n(c) combine Customer Personal Data with Personal Data received from or on behalf of other customers or collected from PixlPush’s own interactions with individuals, except as permitted by applicable law for security, fraud prevention, service integrity or another disclosed purpose; or\n\n(d) use Customer Personal Data, End User data, campaign content or AI inputs and outputs to train general-purpose AI models.\n\n4.3. Customer authorizes PixlPush to Process Customer Personal Data to operate, secure, maintain and support the Services; follow Customer’s configuration and instructions; deliver messages and process delivery feedback; generate requested analytics, segments, recommendations, translations and AI outputs; provide exports and deletion; prevent abuse and protect service integrity; and comply with law. Further material purposes require Customer’s documented instructions or an updated Agreement.\n\n4.4. PixlPush may Process limited information as an independent Controller where necessary for its own security, fraud prevention, service integrity, legal obligations or claims. Such Processing is outside this DPA to the extent PixlPush independently determines its purposes and means and is described in the Privacy Policy." },
    { heading: "5. Details of Processing and AI functions", body: "5.1. The processing subject matter, duration, nature, purposes, Data Subjects, Personal Data types and sensitive-data restrictions are set out in Annex 1.\n\n5.2. Customer may use AI-assisted functions through Max, Ben, Nova, Anna and AI Translations by actively invoking the feature or assigning a task. AI does not independently initiate background tasks without a user instruction. AI recommendations alone do not initiate message delivery. A customer-configured and activated journey may send messages automatically under Customer’s rules.\n\n5.3. PixlPush uses the Google Gemini API through Google AI Studio, not Vertex AI, as an AI provider. The applicable provider data terms depend on the production account, billing status, service and configuration. The parties acknowledge that:\n\n(a) Google’s Gemini API terms distinguish paid and unpaid services;\n\n(b) Google’s published terms state that unpaid services may use submitted content and generated responses to provide, improve and develop Google products and machine-learning technologies and may involve human review;\n\n(c) Google’s published terms state that paid services do not use prompts and responses to improve Google products, but may log them for a limited period for safety, security and legal purposes and may store such data in countries where Google or its agents operate; and\n\n(d) Google states that access to AI Studio is treated as a paid service when the account has an active Cloud Billing account or is a Workspace enterprise account, and that only paid services may be used for API clients available to individuals in the EEA, Switzerland or UK.\n\n5.4. Before production Processing of Customer Personal Data through AI, PixlPush must verify that the applicable paid-service terms, billing account, permissions and settings are in effect for the production project; that any required Google data processing terms are accepted; and that any logging, retention, grounding, file or context features are understood and configured. Until those checks are complete, Customer shall not submit sensitive, confidential or unnecessary Personal Data through AI. The Subprocessor List must identify the applicable Google AI service and its role and transfer details.\n\n5.5. AI output may be inaccurate or incomplete. Customer is responsible for reviewing output, translations, audience selections and campaign settings before use. Nothing in this DPA makes PixlPush responsible for Customer’s legal basis, notices, recipients, message content or decision to activate an automated journey." },
    { heading: "6. Subprocessors", body: "6.1. Customer grants PixlPush general written authorization to engage the Subprocessors identified in the then-current Subprocessor List for the activities described there. The list must distinguish:\n\n(a) providers that Process Customer Personal Data as Subprocessors;\n\n(b) providers used only for PixlPush’s own Controller data, such as CRM and billing;\n\n(c) website-only analytics, advertising or consent providers; and\n\n(d) infrastructure providers that do not receive routine Customer Personal Data but may process limited technical or routing data.\n\n6.2. The current Subprocessor List is available at:\n\nhttps://pixlpush.com/legal/subprocessors\n\nPixlPush maintains a Subprocessor List that identifies each provider, its function, the categories of data it receives, its processing locations, its transfer mechanism and the date on which the provider was added. The production Subprocessor framework is as follows: Supabase provides the primary PostgreSQL database, authentication support and object storage; Vercel provides frontend hosting and may process request metadata and application delivery logs; Google Cloud and Firebase provide authentication, application and messaging services; BigQuery is used for analytics or warehousing where configured; Google Gemini API / Google AI Studio provides the server-side AI functions; Amazon SES provides email delivery; Amazon SNS receives email delivery feedback; Cloudflare provides domain, DNS and security-edge services where enabled; CookieYes manages PixlPush website consent; Google Analytics provides website analytics; Google Ads and Meta provide website advertising measurement and attribution; HubSpot is used for PixlPush’s own CRM and business contacts; and Stripe is used for PixlPush account billing and payment processing. HubSpot and Stripe do not receive Customer Personal Data through the Services unless separately disclosed and authorised. The Subprocessor List is incorporated into this DPA by reference and is updated when a provider, purpose, data category, region or transfer mechanism changes.\n\n6.3. Before adding or replacing a Subprocessor that will Process Customer Personal Data, PixlPush will provide notice at least 30 days in advance through the customer account’s designated administrative email or another published notice channel. Customer must keep its contact information current. The notice will identify the new or replacement Subprocessor, its function and the expected start date and link to the updated list.\n\n6.4. Customer may object in writing within 30 days after notice on reasonable and documented grounds relating to data protection. The parties will work in good faith to resolve the objection, including by clarifying the provider’s safeguards, applying a reasonable technical or contractual mitigation, or identifying an alternative where commercially and technically feasible. If no reasonable solution is available, either party may terminate only the affected feature or Services that cannot reasonably be provided without the objected Subprocessor, subject to the termination and refund terms in the Agreement. Any refund of prepaid unused fees will be determined under the Agreement and applicable law.\n\n6.5. PixlPush shall impose data-protection obligations on each Subprocessor no less protective in substance than the obligations applicable to PixlPush under this DPA, to the extent relevant to the services provided. PixlPush remains responsible to Customer for its Subprocessors’ performance of their data-protection obligations to the extent required by applicable law.\n\n6.6. On reasonable written request, PixlPush will provide information about Subprocessors and, where necessary to demonstrate compliance, relevant summaries or redacted extracts of their data-processing terms, subject to confidentiality, security and third-party restrictions." },
    { heading: "7. International transfers", body: "7.1. PixlPush is operated by PIXLLOVE SOCIAL MEDIA APPLICATIONS DEVELOPMENT AND MANAGEMENT L.L.C. from the United Arab Emirates. PixlPush will maintain the primary Customer Data database and Customer Data object storage in an EU region of the selected infrastructure provider where the service supports a regional choice. The PixlPush frontend may be delivered through a global content-delivery or edge network and may therefore process limited request metadata outside the EU. Amazon SES and Amazon SNS are configured for the EU North (Stockholm) region where used. Google Gemini, Firebase/FCM, Google Analytics, Google Ads, Meta, Stripe and other global providers may process limited data in the countries where they or their subprocessors operate. Each such transfer is governed by the transfer mechanism and supplementary safeguards described in this DPA and the Subprocessor List.\n\n7.2. Before a transfer of Customer Personal Data restricted by GDPR Chapter V, UK GDPR or Swiss FADP occurs, the parties shall ensure an applicable transfer mechanism is in place. Depending on the parties’ locations and roles, this may be an applicable adequacy decision, the SCCs, the UK International Data Transfer Addendum to the SCCs or UK International Data Transfer Agreement, Swiss adaptations to the SCCs, or another mechanism permitted by the applicable law.\n\n7.3. Where SCCs are required:\n\n(a) the parties incorporate the SCCs by reference, without modification except as permitted by the SCCs;\n\n(b) the applicable module shall be selected based on the actual roles: Module 2 for Controller-to-Processor or Module 3 for Processor-to-Processor; another module will not be used unless the actual transfer requires it;\n\n(c) the SCCs’ optional docking clause is included;\n\n(d) the optional language in Clause 11(a) is not included;\n\n(e) for Clause 17, the governing law shall be the law of Ireland, subject to counsel confirming an appropriate EU Member State and the requirements of the SCCs;\n\n(f) for Clause 18, the courts shall be those of Ireland, subject to counsel confirming the competent forum; and\n\n(g) Annex I and Annex II shall be completed with the parties, transfer details, competent authority and actual technical and organizational measures before transfer.\n\n7.4. For UK restricted transfers, the parties shall complete and incorporate the then-current UK Addendum issued by the UK Information Commissioner or enter into the UK IDTA, as appropriate. Tables, importer/exporter details, transfer description and security measures must be completed for the actual transfer.\n\n7.5. For Swiss restricted transfers, the parties shall apply the SCCs with the adaptations required by the Swiss FDPIC and Swiss FADP. The competent authority and governing forum shall be specified in the completed transfer schedule.\n\n7.6. PixlPush maintains a transfer record for every restricted international transfer. The record identifies the provider, service, exporter, importer, data categories, destination, remote-access locations, transfer mechanism, SCC module where applicable, transfer impact assessment and supplementary measures. For EEA transfers, PixlPush uses an adequacy decision where available and otherwise the applicable SCC module under Commission Implementing Decision (EU) 2021/914. For UK transfers, PixlPush uses the UK Addendum or UK IDTA. For Swiss transfers, PixlPush applies the Swiss adaptations to the SCCs. PixlPush reviews these records when a provider, service, region, law or transfer route changes." },
    { heading: "8. Security Incidents and cooperation", body: "8.1. PixlPush will notify Customer without undue delay after becoming aware of a Security Incident affecting Customer Personal Data. The contractual target is to provide an initial notice within 48 hours after confirmation where reasonably practicable. If all details are not then available, PixlPush may provide information in phases as it becomes available.\n\n8.2. The notice will, to the extent known and reasonably available, describe the nature of the Security Incident, affected data or systems, likely consequences, containment and remediation measures, and a contact point for follow-up. PixlPush will take reasonable steps to contain, investigate and mitigate the incident and will provide reasonable cooperation to Customer.\n\n8.3. The notice is not an admission of fault or liability. Customer is responsible for determining and making notices to Data Subjects, regulators and other parties, except to the extent applicable law places an obligation directly on PixlPush. Customer shall not identify PixlPush in a public notice as having caused an incident without first discussing the factual description with PixlPush, unless required by law.\n\n8.4. PixlPush will reasonably assist Customer with security obligations, DPIAs, prior consultations and regulator inquiries to the extent the information is available to PixlPush and relevant to the Services. Customer will reimburse reasonable costs for assistance that is materially beyond the standard functionality or obligations under applicable law, where permitted by the Agreement and law." },
    { heading: "9. Data Subject requests", body: "9.1. If PixlPush receives a request from a Data Subject concerning Customer Personal Data, PixlPush will, where legally permitted, refer the person to Customer and notify Customer without undue delay. PixlPush will not substantively respond unless instructed by Customer or required by law.\n\n9.2. Taking into account the nature of Processing, PixlPush will provide reasonable technical and organizational assistance to enable Customer to respond to requests to access, correct, delete, restrict, export or otherwise exercise rights under applicable law, insofar as Customer cannot reasonably fulfill the request using available Services functionality.\n\n9.3. Customer shall make the determination whether a request is valid and how to respond, shall use available product controls where appropriate, and shall respond within the time required by law. PixlPush may request information reasonably necessary to verify that an instruction came from Customer’s authorized representative.\n\n9.4. Customer shall reimburse PixlPush for assistance beyond standard product functionality where the request is excessive or requires substantial manual effort, to the extent allowed by the Agreement and applicable law." },
    { heading: "10. Compliance information and audits", body: "10.1. PixlPush will make available information reasonably necessary to demonstrate its compliance with this DPA, including relevant summaries of security measures and subprocessor information, subject to confidentiality and security restrictions.\n\n10.2. Customer may audit PixlPush’s Processing of Customer Personal Data where required by applicable law and where the information made available under Section 10.1 is insufficient. Customer shall:\n\n(a) give at least 30 days’ written notice, except where an urgent audit is required by a competent authority or following a Security Incident;\n\n(b) conduct no more than one audit in a 12-month period unless required by law, a regulator or a Security Incident;\n\n(c) agree in advance with PixlPush on the scope, timing, auditor, confidentiality and security arrangements;\n\n(d) use an independent auditor bound by confidentiality and not a competitor of PixlPush; and\n\n(e) avoid unreasonable disruption and protect the data and systems of other customers.\n\n10.3. An audit shall be limited to controls and records relevant to this DPA. It does not entitle Customer or its auditor to access another customer’s data, production credentials, source code, physical data-center areas or systems whose disclosure would create a security risk. PixlPush may satisfy audit requests through current third-party reports, certifications actually held, questionnaires, evidence summaries or a remote review where those materials adequately address the request.\n\n10.4. Each party shall bear its own audit costs unless the audit identifies a material breach by PixlPush or applicable law requires a different allocation. Any cost allocation must remain subject to mandatory law." },
    { heading: "11. Return, deletion and retention", body: "11.1. During the term, Customer may use available export and deletion functionality and may submit documented instructions for Customer Personal Data. Customer is responsible for exporting data it wishes to retain before its access ends.\n\n11.2. At the end of the Services, PixlPush will, at Customer’s choice, delete or return Customer Personal Data in its possession or control, subject to the retention periods and exceptions in this Section. The available choice and method must be exercised within the applicable export period.\n\n11.3. For frozen, cancelled and non-reactivated accounts, PixlPush applies the following retention and deletion schedule:\n\n(a) operational Customer Personal Data remains available for up to 12 months after the account enters the applicable frozen or inactive state;\n\n(b) after 12 months, PixlPush sends a final deletion notice and allows an additional 30 days for reactivation, export or deletion;\n\n(c) after that additional period, operational Customer Personal Data is deleted or irreversibly anonymized, unless an exception applies;\n\n(d) during a frozen state, the service does not store new users or tracking events and does not send new email or push messages; billing, payment, export and deletion remain available; and\n\n(e) events not recorded during the frozen period are not collected retroactively after reactivation.\n\n11.4. PixlPush implements the lifecycle controls in Section 11.3 through account-state enforcement, worker restrictions, export controls and a scheduled deletion job. The deletion job records the account, project, data categories, deletion timestamp, deletion result and any lawful retention exception. Deleted Customer Personal Data is not restored except where required for a documented legal, security or disaster-recovery purpose.\n\n11.5. Backups containing Customer Personal Data are encrypted, access-restricted and overwritten or rendered irreversibly inaccessible no later than 30 days after deletion from the primary systems, subject to the backup architecture of the relevant infrastructure provider. Backup copies are not used for ordinary Processing. If a backup is restored, PixlPush re-applies deletion requests and the applicable retention controls within a reasonable operational period and records the restoration and deletion event.\n\n11.6. PixlPush may retain limited information where required by law or necessary for tax, accounting, contract, payment, security, abuse prevention, suppression enforcement or the establishment, exercise or defense of legal claims. Such information is access-restricted and used only for the applicable purpose. Security and audit logs are retained for up to 24 months unless a longer period is required for an incident or legal claim. AI conversations are retained for up to 12 months unless Customer or an authorised administrator deletes them earlier. Bounce, complaint and unsubscribe suppression records are retained for as long as necessary to prevent renewed unwanted communication and to demonstrate compliance, after which they are deleted or anonymised. Statutory accounting and tax records are retained for the period required by applicable law.\n\n11.7. On written request, PixlPush will confirm deletion or return after completion, except for information retained under Section 11.6 or in backups pending scheduled overwrite." },
    { heading: "12. Confidentiality and personnel", body: "12.1. PixlPush will ensure that personnel authorized to Process Customer Personal Data are subject to confidentiality obligations and receive access only as necessary for their assigned functions.\n\n12.2. Customer shall ensure that its Authorized Users are bound by appropriate confidentiality and security obligations and that access is promptly changed or revoked when no longer needed." },
    { heading: "13. Technical and organizational measures", body: "13.1. PixlPush will maintain technical and organizational measures appropriate to the risks of Processing, as set out in Annex 2. Measures may be updated as technology and risks evolve, provided that updates do not materially reduce the overall level of protection for Customer Personal Data.\n\n13.2. PixlPush maintains the technical and organisational measures in Annex 2 as the minimum security baseline for the Services. PixlPush does not claim SOC 2, ISO 27001, ISO 27701, HIPAA or another certification unless a current certificate or attestation is specifically identified in the Security & Privacy documentation.\n\n13.3. Customer is responsible for its own secure configuration and use of the Services, including access management, safeguarding credentials, lawful SDK deployment, endpoint security, secure transmission, and any backups or records Customer is required to retain." },
    { heading: "14. Liability and precedence", body: "14.1. Each party’s liability under this DPA is subject to the liability provisions of the Agreement, except to the extent a limitation or exclusion is prohibited by applicable law or cannot apply to the relevant data-protection obligation, Data Subject right or regulatory responsibility.\n\n14.2. Nothing in this DPA excludes or limits liability for fraud, willful misconduct, death or personal injury where such limitation is prohibited, or any other liability that cannot lawfully be excluded or limited. The parties’ responsibility for administrative fines, indemnities, third-party claims and contribution between them must be interpreted under the Agreement and applicable law; this DPA does not transfer a party’s non-delegable statutory obligations.\n\n14.3. No party may use this DPA to exclude Data Subjects’ rights or rights of competent supervisory authorities." },
    { heading: "15. General terms", body: "15.1. Notices under this DPA shall be sent to the administrative or legal contact maintained in the Customer account and to PixlPush at contact@pixl-develop.com, unless the parties agree another notice address in writing.\n\n15.2. If any provision of this DPA is invalid or unenforceable, the remaining provisions remain effective, and the invalid provision shall be replaced by a valid provision that most closely reflects its purpose, subject to applicable law.\n\n15.3. This DPA is governed by the governing-law and forum provisions of the Agreement, except that mandatory Data Protection Laws and the SCCs, UK Addendum, UK IDTA or Swiss adaptations govern where they require a different rule. The Terms of Service’s governing law and forum remain subject to final confirmation and legal review.\n\n15.4. This DPA may be accepted electronically and in counterparts. Customer’s authorized representative must have authority to bind Customer. The mechanism for recording acceptance, version, timestamp and accepting account must be implemented and verified before electronic acceptance is relied upon." },
    { heading: "ANNEX 1 — DETAILS OF PROCESSING", body: "A. Parties and roles\n\nData exporter / Controller: Customer identified in the applicable Agreement or order.\n\nData importer / Processor: PIXLLOVE SOCIAL MEDIA APPLICATIONS DEVELOPMENT AND MANAGEMENT L.L.C., Building Name – ALSUAIDI / Plot Number 247-0 / Property Number 1F01, Dubai, United Arab Emirates.\n\nCustomer acting as Processor: where Customer processes data on another Controller’s behalf, Customer is the exporter/Processor and PixlPush is the importer/Subprocessor; Module 3 SCCs may apply.\n\nB. Subject matter\n\nCustomer’s use of PixlPush’s B2B customer-engagement, marketing-automation, analytics and lifecycle-communication platform.\n\nC. Duration\n\nFor the term of the Services, followed by return or deletion in accordance with Section 11 and the Agreement, subject to mandatory retention and backup-overwrite periods.\n\nD. Nature of Processing\n\nReceiving, recording, organizing, hosting, retrieving, consulting, using, transmitting, synchronizing, analyzing, segmenting, generating recommendations or translations, automating, sending communications, recording delivery feedback, exporting, restricting, deleting and destroying Personal Data as configured or instructed by Customer.\n\nE. Purposes\n\nTo provide and support the Services selected by Customer, including imports, SDK/API collection, user and audience management, segmentation, campaign and journey orchestration, email, push and in-app communications, analytics, performance and retention analysis, AI-assisted recommendations and content generation, translation, delivery feedback, export and deletion.\n\nF. Data Subjects\n\n• Customer’s End Users, app or website users and message recipients;\n\n• individuals whose data Customer imports or sends through an SDK, API or integration;\n\n• Customer’s employees, contractors, administrators and other Authorized Users, only to the extent Customer submits their data as Customer Personal Data; and\n\n• other individuals whose Personal Data Customer chooses to include in a permitted payload.\n\nG. Categories of Personal Data\n\n• identifiers and contact details, including external IDs, names and email addresses;\n\n• country or region, language and time zone;\n\n• device identifiers, SDK identifiers, push tokens, IP addresses and technical data;\n\n• consent, permission, preference, unsubscribe and suppression information;\n\n• app, website, subscription, onboarding, paywall, lifecycle and other event data submitted by Customer;\n\n• campaign, template, segment, audience, journey, message and automation data;\n\n• message delivery, bounce, complaint, open or click data where enabled;\n\n• customer-defined properties and attributes;\n\n• AI prompts, instructions, context and outputs submitted or generated through the Service; and\n\n• other data Customer elects to submit, subject to the restrictions in Section 3.4.\n\nH. Special categories and criminal-offence data\n\nNot permitted unless PixlPush gives prior written approval following legal and technical review and the parties agree additional safeguards. Customer must not submit children’s or minors’ data without such approval.\n\nI. Frequency and transfer\n\nContinuous, as required by Customer’s use of the Services, SDKs, APIs, imports, integrations and automated workflows.\n\nJ. Retention\n\nAs described in Section 11 and the Privacy Policy. Provider-specific retention and backup periods are recorded in the Subprocessor List and the Data Retention Schedule and are applied through the relevant provider configuration and deletion controls." },
    { heading: "ANNEX 2 — TECHNICAL AND ORGANIZATIONAL MEASURES", body: "The following measures form PixlPush’s mandatory security baseline for the Services. PixlPush maintains evidence of implementation through access records, configuration records, security logs, testing records, provider agreements and incident records." },
    { heading: "1. Governance and confidentiality", body: "• Confidentiality obligations for persons authorized to access Customer Personal Data.\n\n• Role-based access and least-privilege principles, to the extent deployed.\n\n• Access authorization and removal procedures to be confirmed and documented." },
    { heading: "2. Authentication and access control", body: "• Email/password and Google sign-in are supported; Google authentication uses Firebase.\n\n• Email verification, password reset, session controls and multi-factor authentication are supported or planned according to the relevant product configuration.\n\n• Strong-password rules, MFA for privileged and administrator accounts, periodic access reviews and prompt removal of unnecessary privileges are enforced." },
    { heading: "3. Data separation and application security", body: "• Customer workspaces and projects are designed for logical tenant separation.\n\n• Application authorization checks, project scoping, tenant isolation and role permissions restrict access to the correct workspace.\n\n• Secure development practices may include code review, automated and manual tests, dependency updates and vulnerability remediation; the actual release controls and coverage must be documented." },
    { heading: "4. Encryption and secrets", body: "• Encryption in transit is enforced for external and internal service connections using supported secure transport protocols.\n\n• Provider-managed encryption at rest may be available depending on provider and configuration; exact systems, algorithms, key controls and exceptions must be verified.\n\n• API keys, passwords and service credentials are stored in protected server-side secrets or provider secret stores and are never exposed in public client code or logs.\n\n• No blanket encryption-at-rest or customer-managed-key claim is made unless confirmed." },
    { heading: "5. Logging, monitoring and abuse prevention", body: "• Authentication, administrative, system, delivery and security events may be logged to support troubleshooting, security and abuse prevention.\n\n• Access to logs is restricted to authorised personnel with a documented operational or security need and is itself logged where technically available.\n\n• Log categories, alerting coverage, monitoring responsibilities and retention periods must be established in the production security and retention schedules." },
    { heading: "6. Backups and continuity", body: "• Encrypted backups, recovery procedures, restore testing and documented recovery objectives support restoration of service and data.\n\n• Backup frequency, encryption, access controls, recovery objectives, restore testing, geographic location and the 30-day overwrite objective require production confirmation.\n\n• Backups are not a substitute for Customer’s own legally required exports or records." },
    { heading: "7. Vulnerability and change management", body: "• Code review, automated and manual testing, dependency management, vulnerability remediation and controlled release procedures reduce software risks.\n\n• PixlPush maintains a vulnerability disclosure channel, incident-response plan, escalation contacts and post-incident review process.\n\n• PixlPush performs risk-based external security testing and documents the scope, date, findings and remediation status. Customer-facing claims about testing are limited to the current evidence available in the Security & Privacy documentation." },
    { heading: "8. Incident response", body: "• PixlPush intends to assess, contain, investigate and remediate security incidents and notify affected Customers under Section 8.\n\n• The on-call process, escalation contacts, evidence retention and exercises must be verified and documented before production launch." },
    { heading: "9. Provider controls", body: "• Subprocessor access and safeguards are governed by provider agreements and their applicable technical controls.\n\n• The production region, access locations, subprocessors, transfer safeguards and deletion behavior for each provider must be documented in the Subprocessor List and transfer records.\n\n• No SOC 2, ISO 27001, ISO 27701, HIPAA or other certification is claimed by this Annex." },
    { heading: "1. EEA transfers", body: "Where restricted transfers from the EEA require SCCs, the parties shall incorporate Commission Implementing Decision (EU) 2021/914, selecting Module 2 or Module 3 according to the parties’ roles. The applicable annexes must identify the parties, transfer, competent supervisory authority, security measures, subprocessor authorization and transfer details. The SCC text and appendices shall be made available to Customer on request." },
    { heading: "2. UK transfers", body: "For restricted transfers subject to UK law, the parties shall complete the then-current UK Addendum to the EU SCCs or the UK IDTA, as appropriate. The parties, transfer description, security measures, selected modules and required tables must be completed before transfer." },
    { heading: "3. Swiss transfers", body: "For restricted transfers subject to Swiss law, the parties shall apply the SCCs with the adaptations required by the Swiss FDPIC, including references to Swiss law, the FDPIC and competent Swiss courts where required." },
    { heading: "4. Transfer impact assessment and supplementary measures", body: "The parties shall cooperate in assessing the laws and practices relevant to a restricted transfer and determining whether supplementary technical, contractual or organizational measures are required. A transfer may not rely solely on a generic statement that contractual safeguards exist; the assessment must address the actual provider, data, access, onward transfers and destination." },
    { heading: "5. Completion record", body: "Before the DPA is used for a transfer, PixlPush must record:\n\n• applicable SCC module or other mechanism;\n\n• whether the transfer is EEA, UK or Swiss restricted;\n\n• exporter and importer legal names and contact details;\n\n• categories and frequency of data transferred;\n\n• relevant provider and service;\n\n• destination and support-access locations, as known;\n\n• competent authority and governing-law selections in the SCCs;\n\n• completed Annex I and Annex II information;\n\n• transfer impact assessment and supplementary safeguards where required; and\n\n• date of approval and responsible person." },
    { heading: "ANNEX 4 — SUBPROCESSOR AND RECIPIENT CLASSIFICATION", body: "The public Subprocessor List at https://pixl-push.com/legal/subprocessors provides the current provider, function, data categories, processing locations, transfer basis and notice date for each Subprocessor. PixlPush updates the list when a provider or processing activity changes.\n\nProvider classification based on the currently stated design; final classification depends on the production data flow:\n\n• Supabase — primary database, authentication support and object storage for Customer Personal Data; EU-region deployment, restricted support access and a written data-processing agreement.\n\n• Vercel — frontend hosting and deployment; processes limited request metadata and application delivery logs; edge processing locations and provider safeguards are documented in the transfer record.\n\n• Google Cloud — configured cloud infrastructure; exact products, Customer Data, regions and access terms to be specified.\n\n• Firebase — authentication and configured application services; exact Customer Data fields, project configuration and regions to be specified.\n\n• BigQuery — analytics/data warehousing only if Customer Personal Data is actually routed there; dataset region, access and retention to be specified.\n\n• Google Gemini API / Google AI Studio — server-side AI processing through a paid production account with billing enabled; Customer prompts and responses are not used to improve Google’s general-purpose models under the applicable paid-service terms; access, logging, retention and transfer settings are restricted and documented.\n\n• Amazon SES — email delivery; recipient addresses, message content and delivery metadata may be processed where used for a Customer’s campaigns; AWS region and retention to be specified.\n\n• Amazon SNS — delivery notifications and feedback; event and delivery metadata may be processed; AWS region and retention to be specified.\n\n• Cloudflare — domain and DNS only under the stated design; if proxy, CDN, WAF or other traffic services are enabled, this classification and disclosure must be reassessed.\n\n• Google Analytics, Google Ads and Meta — website or advertising services only where actually enabled and consented; not assumed to receive Customer Data through the SaaS product.\n\n• CookieYes — consent interface for PixlPush websites; not assumed to process Customer Data from customers’ apps or websites.\n\n• HubSpot — PixlPush’s own CRM and business contacts; excluded from Customer Personal Data and technically separated from customer workspaces.\n\n• Stripe — PixlPush account billing and payment processing; receives billing and payment information for the PixlPush account and is excluded from Customer Personal Data.\n\nProvider-specific links and privacy notices are available in the Privacy Policy or Subprocessor List. If an architecture change routes Customer Personal Data to a provider listed here as website-only, CRM or billing, PixlPush must update this DPA, the Subprocessor List and any relevant transfer documentation before enabling that flow." },
    { heading: "IMPLEMENTATION BASELINE", body: "IMPLEMENTATION BASELINE\n\nPixlPush will implement and maintain the architecture, provider contracts, regions, transfer safeguards, Gemini paid-service configuration, security controls, breach-notification workflow, consent records, deletion jobs, backup cycle and retention periods described in this DPA. These controls are the required baseline for production processing of Customer Personal Data and are included in PixlPush’s implementation, release and compliance workstreams." },
  ] },
  "sdk-terms": { title: "SDK Terms & End-User License Agreement", description: "Terms governing installation, licensing and use of the PixlPush SDK.", version: "1.0", effectiveDate: "13 October 2026", sections: [
    { heading: "Overview", body: "Version 1.0\n\nThese SDK Terms & End-User License Agreement (“SDK Terms”) apply to the PixlPush software development kits, client libraries, APIs, sample code, documentation and related integration materials made available by PixlPush (“SDK Materials”). They supplement and form part of the PixlPush Terms of Service (“Terms”). If these SDK Terms conflict with the Terms, these SDK Terms control only for the SDK Materials and SDK-specific use.\n\n1. Grant of license\n\nSubject to the Agreement, payment obligations and continued compliance, PixlPush grants the Customer a limited, non-exclusive, non-transferable, non-sublicensable, revocable and term-limited license to install, integrate and use the applicable SDK Materials in applications, websites and digital products that the Customer owns, operates or is authorized to represent (“Customer Properties”).\n\nThe license is solely to enable the Customer to connect Customer Properties to the PixlPush Services, including identifying End Users, sending permitted events, registering installations and push tokens, and using messaging or analytics functionality made available for the relevant plan and configuration.\n\n2. Authorized use\n\nThe Customer may:\n\n• include the SDK in compiled or bundled Customer Properties;\n\n• use documented SDK APIs and configuration options;\n\n• make reasonable modifications required to integrate the SDK into Customer Properties, provided the modified SDK remains compliant with these SDK Terms;\n\n• use the SDK across development, staging and production environments with the applicable Project and key; and\n\n• distribute the SDK only as embedded in a Customer Property and only to the extent necessary for the Customer’s authorized users or End Users to use that Customer Property.\n\nThe Customer must use a separate Project and SDK key for environments where separation is required and must follow the applicable PixlPush documentation.\n\n3. SDK keys and credentials\n\nA public SDK key identifies a PixlPush Project and is designed to be included in a client application or website. It is not a password or a general-purpose secret.\n\nThe Customer must not place Firebase service-account credentials, private API keys, payment credentials, signing secrets or other confidential credentials in a Customer Property or SDK configuration.\n\nThe Customer must protect its public key against unauthorized use where reasonably practicable, use separate keys for development and production, rotate keys when compromise is suspected and promptly revoke keys that are no longer required. PixlPush may rate-limit, restrict or revoke a key or Project where it is abused, exposed in a harmful manner, used unlawfully or presents a security or delivery risk.\n\n4. Integration responsibilities\n\nThe Customer is responsible for:\n\n• implementing the SDK according to the current documentation;\n\n• testing the integration before production use;\n\n• keeping the SDK, dependencies and Customer Property reasonably current;\n\n• configuring the correct Project, environment, public key and permitted data fields;\n\n• preventing duplicate, fabricated or excessive events;\n\n• maintaining correct user, installation, session and consent handling;\n\n• integrating logout, reset, deletion and opt-out behavior;\n\n• ensuring that SDK calls do not expose secrets or unnecessary personal data; and\n\n• monitoring errors, delivery failures, token invalidation and unexpected behavior.\n\nPixlPush is not responsible for problems caused by an unsupported modification, incorrect integration, incompatible dependency, Customer Property, device, browser, operating system, app store, network or third-party service.\n\n5. Customer Data and SDK Data\n\nData submitted through the SDK, including identifiers, profiles, properties, events, installation data, device data, push tokens, permissions and preferences, is Customer Data where PixlPush processes it on the Customer’s behalf.\n\nThe Customer determines the purposes and means of collection and use in its Customer Properties. The Customer must provide appropriate privacy notices, obtain required permissions and legal bases, honor data-subject rights and configure collection lawfully.\n\nThe Customer must not send passwords, authentication tokens, payment-card data, secret keys, unnecessary special-category data, children’s data, precise continuous location data or confidential third-party information through the SDK unless the Agreement expressly permits the use and the required safeguards are documented.\n\nThe DPA governs processor processing of Customer Data. PixlPush does not use Customer Data, SDK events or SDK inputs to train general-purpose AI models for PixlPush’s benefit.\n\n6. Identity and installation behavior\n\nThe Customer must use a stable Customer User ID only where it has the right to use that identifier. An email address, push token, device identifier or installation identifier does not by itself establish identity or consent.\n\nAn installation represents an app or website installation and may change when an app is reinstalled, a device is replaced or a user changes. Push tokens may rotate, become invalid or be reassigned. The Customer must not use a push token as a permanent person identifier.\n\nThe Customer must call the applicable reset or logout functionality when a user logs out, changes account or withdraws the relevant permission. The Customer remains responsible for implementing account switching and deletion behavior correctly.\n\n7. Push permissions and messaging\n\nThe Customer must obtain and maintain all permissions required for push notifications, in-app messages, device identifiers, SDK events and related communications. The Customer must respect operating-system, browser, app-store, carrier and provider settings.\n\nThe Customer must not send unlawful, deceptive, abusive, harassing, unsafe or unsolicited messages through the SDK or Services. Marketing communications must comply with the Anti-Spam Policy, AUP, Privacy Policy and applicable law.\n\nPixlPush does not guarantee delivery. Delivery may depend on FCM, APNs, web-push services, device settings, token validity, application state, network access, provider availability, platform review or other factors outside PixlPush’s control.\n\n8. Data minimization and security\n\nThe Customer must send only data reasonably necessary for the configured feature and must avoid placing personal data in event names, URLs, logs or unrestricted properties.\n\nThe Customer must use secure transport, reasonable access controls, current dependencies and appropriate environment separation. It must not disable SDK security controls, bypass rate limits, falsify platform metadata or use the SDK to probe, overload or compromise PixlPush infrastructure.\n\n9. Prohibited conduct\n\nThe Customer must not:\n\n• copy, sell, rent, lease, sublicense, distribute or commercially exploit the SDK Materials as a standalone product;\n\n• use the SDK to build a competing SDK, messaging platform or service substantially based on PixlPush;\n\n• reverse engineer, decompile, disassemble or attempt to derive source code, except to the extent a restriction cannot lawfully be enforced;\n\n• remove copyright, license, trademark or attribution notices;\n\n• bypass authentication, key restrictions, rate limits, usage limits or security controls;\n\n• use undocumented endpoints or depend on undocumented behavior;\n\n• interfere with another customer’s Project, data, devices, accounts or keys;\n\n• use the SDK for malware, phishing, fraud, spam, unlawful surveillance or unlawful profiling;\n\n• use the SDK in a way that violates app-store, browser, carrier, platform or third-party terms; or\n\n• use the SDK for decisions producing legal or similarly significant effects without the required human oversight and legal safeguards.\n\n10. Third-party and open-source components\n\nThe SDK may depend on or include third-party or open-source components. Those components may be subject to separate license notices and terms. The Customer must comply with those terms.\n\nThe Customer is responsible for third-party integrations, app-store registrations, certificates, domains, Firebase or APNs configuration, device permissions and provider accounts used with the SDK.\n\n11. Versions, changes and compatibility\n\nPixlPush may release, modify, deprecate, suspend or discontinue SDK versions, APIs, features and integrations. Versioning, support windows and deprecation practices are described in the Software Lifecycle & Versioning Policy.\n\nThe Customer must test updates and migrate before a supported version reaches end of life. PixlPush may introduce breaking changes in a new major version or make urgent changes without advance notice where reasonably necessary for security, law, provider requirements, abuse prevention, compatibility or service availability.\n\nPixlPush does not guarantee that every SDK version remains compatible with every Customer Property, operating system, browser, app store, dependency or third-party service.\n\n12. Intellectual property\n\nPixlPush and its licensors retain all rights, title and interest in the SDK Materials, PixlPush Services, documentation, trademarks and improvements, except for rights expressly granted in the Agreement.\n\nThe Customer retains its rights in Customer Properties and Customer Data. The Customer grants PixlPush only the limited rights necessary to provide, secure, support and improve the Services under the Agreement.\n\nThe Customer may provide feedback about the SDK. PixlPush may use feedback without restriction or compensation, provided that it does not disclose Customer Confidential Information.\n\n13. Suspension and termination\n\nThe license ends automatically when the Agreement or the relevant Service ends, or when the Customer stops using the relevant SDK integration.\n\nPixlPush may suspend, restrict or revoke SDK access, a key, an endpoint or a Project immediately where reasonably necessary to protect security, recipients, providers, the Services or other customers, or where the Customer breaches the Agreement, applicable law or provider requirements.\n\nAfter termination, the Customer must stop using the SDK Materials and remove or disable the SDK from Customer Properties within a reasonable period. Data already collected remains subject to the Terms, Privacy Policy and DPA, including applicable retention, export and deletion rules.\n\n14. Warranty disclaimer and liability\n\nThe SDK Materials are provided on an “as available” basis except for express commitments in the Agreement. PixlPush does not warrant that the SDK or its results will be uninterrupted, error-free, secure against every threat or compatible with every Customer Property.\n\nThe Terms’ warranty disclaimers, indemnities, liability limitations, dispute provisions and other provisions apply to the SDK Materials. Nothing excludes or limits liability that cannot legally be excluded or limited.\n\n15. Changes\n\nPixlPush may update these SDK Terms when the SDK, Services, providers, security practices or applicable law change. The current version will be made available through the PixlPush Legal Hub.\n\nQuestions about the SDK or these SDK Terms may be sent to contact@pixl-develop.com." },
  ] },
  "software-lifecycle": { title: "Software Lifecycle Policy", description: "Versioning, maintenance, support and security update practices.", version: "1.0", effectiveDate: "13 October 2026", sections: [
    { heading: "Overview", body: "Version 1.0\n\nThis Software Lifecycle & Versioning Policy explains how PixlPush classifies, maintains, changes, deprecates and retires software features, APIs, SDKs, integrations and related services.\n\nThis Policy forms part of the Terms of Service where applicable. It describes expected lifecycle practices and does not create an uptime guarantee, service-level commitment or warranty unless an Order or SLA expressly provides one." },
    { heading: "1. Scope", body: "This Policy applies to PixlPush APIs, SDKs, API clients, integrations, dashboards, automation features and other software components made available to Customers.\n\nIt applies to generally available, early-access, beta, alpha, deprecated and end-of-life functionality." },
    { heading: "2.1 Alpha", body: "Alpha features are limited-development features that may be available only by invitation or to selected users. They may change substantially, contain defects, lack complete documentation and be unsuitable for production or business-critical use.\n\nPixlPush may suspend, change or discontinue an Alpha feature at any time without liability." },
    { heading: "2.2 Beta and early access", body: "Beta and early-access features are more developed but may still contain defects, incomplete functionality, performance limitations or breaking changes. They are not subject to the same support, availability or compatibility expectations as generally available features.\n\nCustomers should not rely on Beta or early-access features for critical operations unless an Order expressly states otherwise." },
    { heading: "2.3 Generally available", body: "Generally Available (“GA”) features are released for general customer use. GA status does not guarantee uninterrupted availability, compatibility with every system or that the feature will remain available indefinitely.\n\nGA features remain subject to the Terms of Service, applicable plan limits, provider dependencies, maintenance and security requirements." },
    { heading: "2.4 Deprecated", body: "A deprecated feature is scheduled for replacement or retirement. PixlPush may limit new use, stop adding functionality or require migration to a replacement feature.\n\nPixlPush will generally provide reasonable notice before a planned deprecation. A shorter notice period or immediate change may apply where required for security, legal compliance, provider requirements, abuse prevention or service availability." },
    { heading: "2.5 End of life", body: "An end-of-life feature is no longer supported for production use. PixlPush may disable it, remove access, stop providing support or stop issuing security updates.\n\nCustomers are responsible for migrating before the end-of-life date. PixlPush is not responsible for losses caused by a Customer’s failure to migrate after reasonable notice." },
    { heading: "3. API and SDK versioning", body: "PixlPush may version APIs and SDKs independently. Version numbers, release notes and technical documentation identify supported versions where applicable.\n\nPixlPush may introduce a new major version for breaking changes. Minor and patch updates may add functionality, correct defects, improve security or change implementation details without changing the intended public contract.\n\nCustomers must use supported API and SDK versions and must not rely on undocumented behavior, internal endpoints or reverse-engineered functionality.\n\nPixlPush may reject requests from obsolete, abusive, insecure or unsupported versions." },
    { heading: "4. Breaking changes and deprecation notice", body: "Where reasonably practicable, PixlPush will announce material breaking changes and planned deprecations through the dashboard, documentation, release notes or the contact information associated with the Account.\n\nThe notice period may depend on the nature of the feature, the number of affected customers, the availability of a replacement and the urgency of the change.\n\nNo advance notice is required where immediate action is reasonably necessary to:\n\n• address a security vulnerability;\n\n• comply with law, court order or regulator instruction;\n\n• comply with a provider, app-store, carrier or infrastructure requirement;\n\n• prevent fraud, abuse, spam or material service degradation;\n\n• protect Customer Data, PixlPush or other customers; or\n\n• respond to an emergency or force-majeure event." },
    { heading: "5. Customer migration obligations", body: "The Customer is responsible for testing releases, reviewing documentation, updating integrations, maintaining compatible applications and migrating before a version reaches end of life.\n\nThe Customer should maintain independent backups and a tested rollback or recovery process for Customer Properties and Customer Data.\n\nPixlPush may provide migration documentation or reasonable technical information, but does not guarantee that a Customer’s custom implementation, third-party integration or code will remain compatible." },
    { heading: "6. Third-party dependencies", body: "The Services depend on third-party providers, operating systems, app stores, networks, browsers, hosting infrastructure, payment processors and messaging platforms.\n\nA third party may change, restrict, deprecate or discontinue its service without PixlPush’s control. PixlPush may modify, replace or discontinue an affected PixlPush feature where necessary to respond to that change.\n\nThe Customer must comply with applicable third-party terms and must maintain any required registrations, approvals, app-store listings, domains, certificates and credentials." },
    { heading: "7. Maintenance and emergency changes", body: "PixlPush may perform planned or emergency maintenance, updates, security fixes and infrastructure changes. Maintenance may temporarily reduce availability or functionality.\n\nPixlPush may deploy emergency changes without advance notice where reasonably necessary to protect security, data, availability, deliverability, providers or other customers." },
    { heading: "8. No lifecycle warranty", body: "Lifecycle stages, notices and release practices are operational commitments only. They do not guarantee that a feature will be error-free, uninterrupted, compatible with every environment or available for a particular period.\n\nThe Terms of Service and any applicable SLA control where there is a conflict." },
    { heading: "9. Contact", body: "Questions about lifecycle status, supported versions or migration should be sent to contact@pixl-develop.com.\n\n10. Development, vulnerability management and operational transparency\n\nPixlPush applies security and quality controls throughout planning, code changes, review, testing and deployment. Changes are intended to be reproducible, traceable and controlled, taking account of the affected service, data flows, dependencies and customer impact.\n\nPixlPush may monitor relevant software dependencies and assess reported vulnerabilities based on severity, exploitability, affected functionality and available mitigations. Critical risks may require prioritized patches, temporary restrictions, emergency maintenance or accelerated retirement of an affected component.\n\nWhere reasonably practicable, material releases, planned maintenance and important lifecycle changes may be communicated through release notes, product notices, the status page, documentation or direct communication to the contact associated with the Account. Planned maintenance will generally be announced in advance where practicable, but security, legal, provider, abuse-prevention and emergency measures may require shorter or no advance notice.\n\nIf a feature or service component is discontinued, PixlPush may provide a reasonable transition period, migration information or an alternative where practicable. Legal, security, provider, availability and urgent operational reasons may require a shorter transition period or immediate discontinuation." },
  ] },
  "responsible-disclosure": { title: "Responsible Disclosure", description: "How to report a suspected PixlPush security vulnerability.", version: "3.0", effectiveDate: "13 October 2026", sections: [
    { heading: "Overview", body: "Version 3.0\n\nPixlPush takes the security and confidentiality of its customers, users, integrations and infrastructure seriously. We welcome responsible reports of security vulnerabilities affecting PixlPush systems.\n\nThis Policy is a coordinated vulnerability disclosure process. It is not a bug-bounty program and does not promise monetary compensation." },
    { heading: "1. Purpose and principles", body: "We ask security researchers to:\n\n• test only what is reasonably necessary to demonstrate the issue;\n\n• use only accounts, applications, devices, domains, data and environments they own or are expressly authorized to test;\n\n• avoid accessing, copying, changing or deleting data that does not belong to them;\n\n• stop testing immediately if personal data, Customer Data, credentials or confidential information is encountered;\n\n• protect the confidentiality of the finding and evidence; and\n\n• give PixlPush a reasonable opportunity to investigate and remediate before public disclosure.\n\nThis Policy does not authorize activity that violates applicable law, another person’s rights or the security of systems outside PixlPush’s control." },
    { heading: "2. Scope", body: "Potentially in-scope systems include publicly accessible PixlPush websites, dashboards, APIs, SDKs, authentication flows, account and workspace controls, project isolation, campaign and messaging functions and cloud-facing interfaces operated by PixlPush.\n\nThe scope is limited to systems PixlPush owns or is authorized to test. Third-party products and infrastructure, including cloud providers, app stores, operating systems, email providers, payment providers and integrations, must be reported to their respective owners. PixlPush may assist with coordination but cannot authorize testing of another provider’s systems.\n\nIf you are unsure whether a target is in scope, contact PixlPush before testing and describe the target without sending sensitive evidence." },
    { heading: "3. Reporting channel", body: "Report suspected vulnerabilities confidentially to:\n\ncontact@pixl-develop.com\n\nUse the subject line “Responsible Disclosure – PixlPush”.\n\nDo not send passwords, private keys, API keys, access tokens, database exports, complete credentials, unnecessary personal data or Customer Data in the initial report. If evidence could contain sensitive information, describe the issue first and wait for instructions on a safe transfer method.\n\nDo not report a vulnerability through a public issue tracker, social media, marketing contact or general support channel unless PixlPush specifically instructs you to do so." },
    { heading: "4. Good-faith testing rules", body: "Researchers must:\n\n• comply with applicable local, national and international law;\n\n• use test accounts and test data wherever possible;\n\n• avoid social engineering, phishing, pretexting or attacks against PixlPush staff, customers or suppliers;\n\n• avoid denial-of-service, distributed denial-of-service, flooding, spam or message-delivery attacks;\n\n• avoid actions that degrade, interrupt or materially increase the cost of the Services;\n\n• avoid accessing, downloading, changing, deleting or disclosing another person’s data;\n\n• avoid persistence, lateral movement, credential theft and exfiltration;\n\n• avoid testing against third-party systems;\n\n• avoid physical security testing;\n\n• avoid automated scanning that creates material load; and\n\n• delete or securely destroy any accidentally obtained data after notifying PixlPush." },
    { heading: "5. Prohibited activities", body: "The following activities are not permitted under this Policy:\n\n• DDoS or other availability attacks;\n\n• social engineering of employees, customers or suppliers;\n\n• phishing, spam or fraudulent messages;\n\n• testing with accounts or data that do not belong to the researcher;\n\n• permanent alteration or deletion of data;\n\n• publication of confidential findings before coordination;\n\n• extortion, threats or demands for payment;\n\n• vulnerability scanning that creates material operational risk;\n\n• attempts to access production personal data beyond what is strictly necessary to prove the issue; and\n\n• testing systems operated by third-party providers without their authorization." },
    { heading: "6. Personal data and confidential information", body: "If testing reveals personal data, Customer Data, credentials, secrets or other confidential information, stop testing immediately, do not copy or disclose it, preserve only the minimum evidence necessary and notify PixlPush.\n\nPixlPush may require secure deletion or return of evidence. Researchers must not include sensitive information in screenshots, videos, reports, public posts or communications unless PixlPush expressly requests it through a secure channel." },
    { heading: "7. Report contents", body: "A useful report should include, where available:\n\n• a clear description of the vulnerability;\n\n• the affected URL, API, SDK, feature or component;\n\n• detailed steps to reproduce the issue;\n\n• test account and environment information;\n\n• relevant platforms, operating systems, versions and configurations;\n\n• screenshots, logs, requests, responses or other evidence;\n\n• an assessment of exploitability and impact;\n\n• whether personal data or confidential information was accessed;\n\n• any remediation suggestion; and\n\n• the researcher’s contact details.\n\nPlease preserve relevant evidence and do not alter logs or system data unnecessarily." },
    { heading: "8. Reports that may be declined", body: "PixlPush may decline or treat as informational:\n\n• reports with insufficient information to reproduce the issue;\n\n• generic automated scanner results without demonstrated impact;\n\n• issues already known, previously reported or already fixed;\n\n• theoretical issues without a realistic attack path;\n\n• self-XSS or issues requiring highly unlikely user actions;\n\n• missing security headers without demonstrated exploitability;\n\n• clickjacking without a meaningful state-changing impact;\n\n• rate-limit observations without material security impact;\n\n• outdated browser or operating-system issues;\n\n• version disclosure without a practical exploit;\n\n• spam or abuse reports that do not identify a security vulnerability;\n\n• content or policy complaints unrelated to security; and\n\n• vulnerabilities solely in third-party services." },
    { heading: "9. Severity and response", body: "PixlPush assesses reports based on exploitability, affected data, confidentiality, integrity, availability, user impact, scope and practical risk.\n\nWe may acknowledge a report, request additional information, assign an internal priority, provide progress updates where appropriate, remediate the issue, apply compensating controls or explain why no change is required.\n\nResponse times depend on severity, complexity, evidence quality and the availability of affected systems. This Policy does not create a service-level commitment." },
    { heading: "10. Safe-harbor approach", body: "PixlPush will treat good-faith research that follows this Policy as authorized security research and will not pursue a legal claim solely because the researcher conducted that research in accordance with the Policy.\n\nThis safe-harbor approach does not apply to:\n\n• testing outside the scope of this Policy;\n\n• intentional harm, extortion or unlawful conduct;\n\n• accessing, using or disclosing data beyond what was reasonably necessary;\n\n• violating the rights of another person;\n\n• testing third-party systems; or\n\n• failing to stop after discovering personal data or confidential information.\n\nPixlPush may report unlawful conduct or serious abuse to law enforcement or other competent authorities." },
    { heading: "11. Public disclosure", body: "Do not publicly disclose a vulnerability, exploit, affected data, customer identity or technical details before PixlPush has had a reasonable opportunity to investigate and remediate.\n\nCoordinated disclosure dates may be agreed in writing. PixlPush may object to disclosure where the issue remains exploitable, remediation is incomplete or disclosure would create unreasonable risk." },
    { heading: "12. Third-party vulnerabilities", body: "Reports involving a third-party provider may be shared with that provider where necessary to investigate or remediate the issue. PixlPush will limit disclosure to what is reasonably necessary and will not make representations on behalf of the provider." },
    { heading: "13. Rewards and expenses", body: "This is not a bug-bounty program. PixlPush does not promise payment, compensation, reimbursement or employment for reports.\n\nResearchers must not incur expenses, access paid services or conduct activity that creates costs for PixlPush without prior written authorization.\n\nPixlPush may recognize or thank researchers at its discretion, subject to confidentiality and the researcher’s consent." },
    { heading: "14. Confidentiality and evidence handling", body: "PixlPush will use reasonable measures to restrict access to reports and evidence to people who need the information to evaluate, remediate or legally manage the issue.\n\nResearchers must treat information about PixlPush systems, customers and users as confidential. This obligation applies whether or not PixlPush previously knew about the issue." },
    { heading: "15. No change to other agreements", body: "This Policy does not grant access to the Services, change the Terms of Service, create a warranty or modify the DPA. Customers and Authorized Users remain bound by their applicable agreements." },
    { heading: "16. Changes", body: "PixlPush may update this Policy to reflect security practices, legal requirements, systems, providers or operational needs. The current version will be published in the Legal Hub." },
    { heading: "17. Contact", body: "Responsible disclosure reports and security questions may be sent to:\n\ncontact@pixl-develop.com\n\nPlease use the subject line “Responsible Disclosure – PixlPush”." },
  ] },
  "subprocessors": { title: "Subprocessors", description: "Providers used to operate PixlPush, including purposes and processing regions.", version: "1.0", effectiveDate: "13 October 2026", sections: [
    { heading: "Overview", body: "Version 1.0\n\nThis list identifies the principal third-party providers that PixlPush may use to operate the PixlPush websites, platform, APIs, SDKs, communications, analytics, security and business operations. A provider is relevant only where the corresponding feature or integration is enabled.\n\nThis list supplements the PixlPush Privacy Policy, Data Processing Addendum (“DPA”), Terms of Service, Security & Privacy information, Cookie Policy and AI Policy.\n\n1. General principles\n\nPixlPush uses providers only for documented business, technical, security, delivery, analytics, payment, support or AI purposes. Providers may act as subprocessors for Customer Personal Data, independent controllers for their own legal, billing or security purposes, or both depending on the activity.\n\nProvider locations, support access, retention and onward transfers may depend on the selected plan, region, account configuration, product feature and provider terms. Where a restricted international transfer occurs, PixlPush applies the transfer mechanism required by the DPA and applicable law.\n\nPixlPush does not authorize a provider to use Customer Personal Data to train general-purpose AI models for PixlPush’s benefit. Provider-specific terms, configurations and data-processing terms apply where incorporated into the relevant service.\n\n2. Current provider categories\n\nSupabase\n\nPurpose: database, storage, authentication and backend infrastructure.\n\nPotential data: account data, workspace data, Customer Data, authentication records, events, configuration and logs.\n\nPrivacy information: https://supabase.com/privacy\n\nProcessing location: configured database and storage region; PixlPush targets an EU region where supported.\n\nVercel\n\nPurpose: website hosting, application deployment, serverless execution and delivery infrastructure.\n\nPotential data: website requests, account and technical data, logs, security signals and application content processed by deployed services.\n\nPrivacy information: https://vercel.com/legal/privacy-policy\n\nProcessing location: globally distributed infrastructure may be used depending on deployment and support configuration.\n\nCloudflare\n\nPurpose: DNS, domain, content delivery, security, edge services, bot and abuse protection.\n\nPotential data: IP address, request metadata, security events, DNS and network information.\n\nPrivacy information: https://www.cloudflare.com/privacypolicy/\n\nProcessing location: global edge and support infrastructure may be used.\n\nGoogle Cloud and Firebase\n\nPurpose: cloud infrastructure, authentication, application services, push notification and mobile SDK-related services.\n\nPotential data: account and authentication data, device identifiers, push tokens, app events, delivery and technical metadata.\n\nPrivacy information: https://policies.google.com/privacy\n\nProcessing location: configured Google/Firebase region and global support or service infrastructure, depending on feature.\n\nGoogle BigQuery\n\nPurpose: configured analytics, reporting and data-processing functions.\n\nPotential data: event data, analytics data, identifiers, campaign and performance data.\n\nPrivacy information: https://cloud.google.com/terms/cloud-privacy-notice\n\nProcessing location: configured project and dataset region.\n\nGoogle Analytics\n\nPurpose: website analytics, performance measurement and conversion analysis.\n\nPotential data: consent records, website events, device/browser information, referral data, campaign parameters and approximate location.\n\nPrivacy information: https://policies.google.com/privacy\n\nActivation: non-essential analytics is enabled subject to the applicable consent configuration.\n\nGoogle Ads\n\nPurpose: advertising measurement, conversion attribution, campaign reporting, remarketing and related advertising functions.\n\nPotential data: website events, conversion data, campaign parameters, browser/device information and advertising events.\n\nPrivacy information: https://policies.google.com/privacy\n\nActivation: enabled subject to applicable consent and advertising configuration.\n\nMeta\n\nPurpose: advertising measurement, campaign attribution, audience creation and advertising delivery.\n\nPotential data: website events, conversion data, campaign parameters, browser/device information and advertising events.\n\nPrivacy information: https://www.facebook.com/privacy/policy/\n\nActivation: enabled subject to applicable consent and advertising configuration.\n\nGoogle Gemini / Google AI Studio\n\nPurpose: user-invoked AI assistance, drafting, translation, analysis, recommendations and related AI features.\n\nPotential data: prompts, instructions, submitted source material, campaign content, analytics context and generated outputs.\n\nPrivacy information: https://policies.google.com/privacy\n\nControls: AI requests are subject to the AI Policy, DPA, provider configuration and applicable commercial data-processing terms. Customer Data is not used by PixlPush to train general-purpose AI models.\n\nAmazon SES and Amazon SNS\n\nPurpose: email delivery, mobile messaging and delivery feedback.\n\nPotential data: recipient addresses, message content, delivery status, bounce, complaint, unsubscribe, push or technical metadata.\n\nPrivacy information: https://aws.amazon.com/privacy/\n\nProcessing location: PixlPush email delivery is configured for AWS eu-north-1 where applicable; other service components may use provider-supported locations.\n\nStripe\n\nPurpose: subscriptions, payment processing, invoicing and payment-related fraud controls.\n\nPotential data: billing contact, invoice, subscription, payment status and limited transaction references. Card data is processed in Stripe’s payment environment.\n\nPrivacy information: https://stripe.com/privacy\n\nCookieYes\n\nPurpose: cookie consent management and consent record storage.\n\nPotential data: consent choices, consent version, timestamps, browser/device and technical information required to apply and demonstrate choices.\n\nPrivacy information: https://www.cookieyes.com/privacy-policy/\n\nHubSpot\n\nPurpose: PixlPush’s own CRM and business relationship management.\n\nPotential data: business contact details, communications, support and sales records.\n\nPrivacy information: https://legal.hubspot.com/privacy-policy\n\n3. Provider changes\n\nPixlPush may add, replace or remove providers where reasonably necessary to operate, secure, improve or deliver the Services. PixlPush will update this list and provide notice where required by the DPA or applicable law.\n\nFor subprocessors processing Customer Personal Data, the Customer may object in accordance with the DPA. An objection must identify reasonable and documented data-protection grounds. The parties will seek a reasonable technical or contractual mitigation or an alternative where commercially and technically feasible.\n\n4. Customer responsibilities\n\nCustomers must configure integrations lawfully, provide required notices, obtain required permissions, select appropriate regions and settings where available, and review the provider terms relevant to features they enable. Customer instructions must not require PixlPush to use a provider or transfer data in violation of applicable law.\n\n5. Contact\n\nQuestions or subprocessor objections may be sent to contact@pixl-develop.com.\n\nThis list is effective from the date stated above and should be read with the current PixlPush Legal Hub documents." },
  ] },
  "impressum": { title: "Legal Notice", description: "Company, contact and legal information for PixlPush.", version: "1.4", effectiveDate: "13 October 2026", sections: [
    { heading: "Overview", body: "Version 1.4\n\nThis Legal Notice identifies the legal entity operating PixlPush and provides its business address, contact details and other relevant company information. The information is based on the operator’s current corporate records." },
    { heading: "1. Operator and provider", body: "PIXLLOVE SOCIAL MEDIA APPLICATIONS DEVELOPMENT AND MANAGEMENT L.L.C. operates the PixlPush SaaS platform. PixlPush is a product and is not a separate legal entity." },
    { heading: "2. Business address", body: "PIXLLOVE SOCIAL MEDIA APPLICATIONS DEVELOPMENT AND MANAGEMENT L.L.C.\n\nBuilding Name – ALSUAIDI / Plot Number 247-0 / Property Number 1F01\n\nDubai, United Arab Emirates" },
    { heading: "3. Contact", body: "For general, privacy and legal enquiries:\n\ncontact@pixl-develop.com\n\nTelephone: +971 52 993 7054" },
    { heading: "4. Additional company details", body: "Trade licence number: 1254086.\n\nVAT details, where applicable, are shown on the relevant tax invoice or tax document." },
    { heading: "5. Hosting and technical providers", body: "Depending on the feature used, PixlPush relies on technical providers for hosting, databases, authentication, domain and DNS, cloud infrastructure, analytics, AI, email, push notifications and payment processing. The current Subprocessor & Provider List identifies each provider, purpose, data types, processing location and transfer approach: https://pixlpush.com/legal/subprocessors" },
    { heading: "6. Product", body: "PixlPush is a B2B SaaS platform for customer engagement, marketing automation, analytics and lifecycle communication. It supports user imports, SDK and API integrations, segmentation, email, push and in-app communication, campaigns, journeys, analytics, translations and AI-assisted recommendations and content." },
    { heading: "7. Legal documents", body: "The PixlPush Legal Hub contains the following applicable and supplementary documents:\n\n• PixlPush – Terms of Service\n• PixlPush – Privacy Policy\n• PixlPush – Cookie Policy\n• PixlPush – Acceptable Use Policy\n• PixlPush – Anti-Spam Policy\n• PixlPush – AI Policy\n• PixlPush – Security & Privacy\n• PixlPush – GDPR & Compliance Overview\n• PixlPush – Data Processing Addendum (DPA)\n• PixlPush – Software Lifecycle & Versioning Policy\n• PixlPush – Responsible Disclosure Policy\n• PixlPush – Subprocessor & Provider List\n• PixlPush – Legal Notice\n• PixlPush – SDK Terms & End-User License Agreement\n\nThis Legal Notice is effective from the date stated above and should be read together with the current PixlPush Legal Hub documents." },
  ] },
};

const AI_CONTROL_SECTIONS: Record<string, LegalSection> = {
  privacy: {
    heading: "12.1. AI feature controls",
    body: "AI features are optional and are controlled at workspace level by the workspace administrator. When AI features are disabled for a workspace, PixlPush will not send new prompts, source material, Customer Data or other workspace content to an AI provider for optional AI features. This does not affect processing that is strictly necessary for security, abuse prevention, legal compliance or another separately disclosed purpose. Disabling AI does not automatically delete historical AI records; deletion remains subject to the applicable retention and deletion rules in this Policy and the DPA."
  },
  terms: {
    heading: "22.1. AI feature controls",
    body: "AI-assisted features are optional. A workspace administrator may disable them for the relevant workspace. Once disabled, PixlPush will not process new workspace content through optional AI features or send it to an AI provider, except where processing is strictly necessary for security, abuse prevention, legal compliance or another separately disclosed purpose. The Customer is responsible for configuring the workspace setting and informing Authorized Users of the applicable restrictions."
  },
  "ai-policy": {
    heading: "8. Workspace AI control",
    body: "AI features are optional and should be controlled through a workspace-level administrator setting. When the setting is disabled, optional AI features must not receive new prompts, source material, Customer Data or other workspace content. Disabling AI does not delete historical prompts or outputs automatically; deletion follows the Privacy Policy, DPA and applicable retention rules. Re-enabling AI is an affirmative administrator action."
  },
  dpa: {
    heading: "5.6. Customer control of optional AI processing",
    body: "AI-assisted processing is optional and subject to the Customer’s workspace configuration and documented instructions. Where the Customer disables optional AI features for a workspace, PixlPush will not send new Customer Personal Data or other Customer Data from that workspace to an AI provider for those features. This restriction does not prevent processing required for security, abuse prevention, legal compliance or another separately documented purpose. Historical AI records remain subject to the deletion and retention provisions of this DPA."
  },
  security: {
    heading: "9. AI feature control",
    body: "PixlPush provides a workspace-level administrative control for optional AI-assisted features. Disabling the control prevents new optional AI requests from sending workspace content to an AI provider. PixlPush applies this setting as a service-control measure; it does not by itself delete historical records, which remain subject to the applicable retention and deletion controls."
  }
};

export const LEGAL_DOCUMENTS: Record<string, LegalDocument> = Object.fromEntries(
  Object.entries(BASE_LEGAL_DOCUMENTS).map(([slug, document]) => {
    const addition = AI_CONTROL_SECTIONS[slug];
    if (!addition) return [slug, document];
    return [slug, { ...document, version: (Number(document.version) + 0.1).toFixed(1), sections: [...document.sections, addition] }];
  }),
) as Record<string, LegalDocument>;
